/**
 * test_bank_diw.js — Diseño de Interfaces Web (DIW)
 * 6 Unidades × 42 preguntas = 252 preguntas
 * 2º DAW — Banco de preguntas oficial
 */
const TEST_BANK_DIW = [

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 1 — Planificación de Interfaces Gráficas y UX
  // ════════════════════════════════════════════════════════════════
  { concept_id:"diw_u1_q1", unit:1, question:"¿Cuál es la diferencia fundamental entre UX (Experiencia de Usuario) y UI (Interfaz de Usuario)?", options:["UX es para móviles y UI para ordenadores, concepto diferente al que se describe en esta pregunta","UI se enfoca en el aspecto visual e interactivo (colores, tipografía","UX es programación backend y UI es frontend, concepto diferente al que se describe en esta pregunta","Son exactamente lo mismo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"UI es la interfaz visual concreta con la que el usuario interactúa; UX es el proceso estratégico completo orientado a satisfacer las necesidades del usuario.", noShuffle:false },
  { concept_id:"diw_u1_q2", unit:1, question:"¿Qué es un 'Wireframe' en el proceso de diseño de interfaces?", options:["El código fuente final en HTML/CSS, concepto diferente al que se describe en esta pregunta","Un esquema o boceto estructural de baja fidelidad que define la jerarquía de contenidos y la distribución de elementos sin diseño visual definitivo (sin colores ni tipografías finales)","Una animación interactiva, concepto diferente al que se describe en esta pregunta","El logotipo vectorial de la web, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los wireframes permiten validar la estructura y el flujo de navegación antes de invertir tiempo en diseño visual o maquetación.", noShuffle:false },
  { concept_id:"diw_u1_q3", unit:1, question:"¿Cuál es la diferencia entre un Wireframe, un Mockup y un Prototipo?", options:["No hay diferencia, aunque algunos enfoques establecen matices al respecto","Wireframe: estructura en baja fidelidad; Mockup: representación visual estática de alta fidelidad con diseño y colores finales; Prototipo: maqueta interactiva y navegable que simula el funcionamiento real","Prototipo es el código en JavaScript, concepto diferente al que se describe en esta pregunta","Mockup es una base de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es la evolución progresiva del diseño: de la estructura básica (wireframe) a la imagen visual fidedigna (mockup) y la simulación funcional (prototipo).", noShuffle:false },
  { concept_id:"diw_u1_q4", unit:1, question:"¿Qué es la 'Arquitectura de la Información' (AI) en el diseño web?", options:["El diseño del cableado del servidor, concepto diferente al que se describe en esta pregunta","El arte y la ciencia de organizar, estructurar y etiquetar los contenidos y secciones de una aplicación web para que los usuarios encuentren la información con facilidad","La base de datos relacional, concepto que se aplica en un contexto distinto","La elección del framework de CSS, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La AI define la taxonomía, menús, mapas de sitio y sistemas de búsqueda para una navegación intuitiva.", noShuffle:false },
  { concept_id:"diw_u1_q5", unit:1, question:"¿Qué técnica de investigación UX consiste en pedir a los usuarios que agrupen tarjetas con temas en categorías lógicas?", options:["A/B Testing, concepto diferente al que se describe en esta pregunta","Card Sorting (Agrupación de Tarjetas)","Eye Tracking, concepto diferente al que se describe en esta pregunta","Shadowing, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Card Sorting (abierto o cerrado) ayuda a diseñar menús y arquitecturas de información que coincidan con los modelos mentales de los usuarios reales.", noShuffle:false },
  { concept_id:"diw_u1_q6", unit:1, question:"¿Cuáles son las '10 Heurísticas de Usabilidad' formuladas por Jakob Nielsen?", options:["Diez reglas de programación en C, concepto diferente al que se describe en esta pregunta","Un conjunto de diez principios generales empíricos de diseño de interacción para evaluar y garantizar la usabilidad de una interfaz","Diez fuentes de Google Fonts recomendadas, concepto diferente al que se describe en esta pregunta","Diez leyes de derechos de autor en la web, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las heurísticas de Nielsen (visibilidad del estado del sistema, correspondencia con el mundo real, control y libertad, etc.) son el estándar de auditoría de usabilidad.", noShuffle:false },
  { concept_id:"diw_u1_q7", unit:1, question:"¿Qué establece la heurística de Nielsen 'Visibilidad del estado del sistema'?", options:["Que la pantalla siempre tenga luz, concepto diferente al que se describe en esta pregunta","Que la interfaz debe mantener siempre informado al usuario de lo que está ocurriendo, mediante retroalimentación oportuna en tiempo razonable","Que el código fuente sea de código abierto, concepto diferente al que se describe en esta pregunta","Que no haya ventanas ocultas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El usuario nunca debe dudar de si el sistema se ha congelado o está procesando una acción.", noShuffle:false },
  { concept_id:"diw_u1_q8", unit:1, question:"¿Qué describe la 'Ley de Fitts' en el diseño de interfaces interactivas?", options:["El tiempo de descarga de las imágenes, aunque este indicador se calcula de forma diferente","El tiempo necesario para alcanzar un objetivo depende de la distancia hasta él y de su tamaño: elementos más grandes y cercanos son más rápidos y fáciles de clicar","El número de palabras por párrafo, concepto que se aplica en un contexto distinto","El contraste entre texto y fondo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Explica por qué botones de acción importantes (CTAs) en pantallas táctiles deben ser amplios y situarse en zonas accesibles para el pulgar.", noShuffle:false },
  { concept_id:"diw_u1_q9", unit:1, question:"¿Qué describe la 'Ley de Hick' (o Hick-Hyman)?", options:["El tiempo que tarda una persona en tomar una decisión aumenta logarítmicamente con el número y la complejidad de las opciones presentadas","La velocidad del scroll, concepto diferente al que se describe en esta pregunta","El consumo de memoria de una fuente tipográfica, concepto que se aplica en un contexto distinto","El ratio de contraste mínimo, concepto que se aplica en un contexto distinto"], correct:0, explanation:"Para agilizar la conversión y evitar la parálisis por análisis, las interfaces deben simplificar opciones y desglosar procesos complejos en pasos sencillos.", noShuffle:false },
  { concept_id:"diw_u1_q10", unit:1, question:"¿Qué describe la 'Ley de Jakob' del diseño de experiencias de usuario?", options:["Los usuarios pasan la mayor parte de su tiempo en otros sitios web","Los usuarios leen todo el texto con atención, concepto diferente al que se describe en esta pregunta","Las páginas deben tener fondos oscuros, concepto diferente al que se describe en esta pregunta","Los botones deben ser siempre cuadrados, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Aprovechar convenciones establecidas (carrito arriba a la derecha, logo para volver al inicio) reduce la carga cognitiva del usuario.", noShuffle:false },
  { concept_id:"diw_u1_q11", unit:1, question:"¿Qué es el patrón de lectura en 'F' descubierto por Jakob Nielsen mediante Eye Tracking?", options:["Leer solo palabras que empiezan por F, concepto diferente al que se describe en esta pregunta","El patrón visual dominante con el que los usuarios escanean páginas web con mucho texto: leen en horizontal la parte superior, bajan leyendo otra línea más corta y escanean el borde izquierdo hacia abajo","Leer de abajo a arriba, concepto diferente al que se describe en esta pregunta","Leer en diagonal saltando párrafos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Implica que la información más crítica y palabras clave deben colocarse al inicio de los párrafos y en la zona superior izquierda.", noShuffle:false },
  { concept_id:"diw_u1_q12", unit:1, question:"¿Qué es el patrón de lectura en 'Z' en páginas web?", options:["Un fallo en la carga del CSS, concepto diferente al que se describe en esta pregunta","El movimiento ocular típico en páginas con poco texto y fuerte carga visual (como landing pages): de izquierda a derecha arriba, diagonal abajo a la izquierda y barrido a la derecha finalizando en el CTA","Leer saltando letras, concepto diferente al que se describe en esta pregunta","Un formato de compresión, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Guía el diseño de landings colocando el logotipo arriba a la izquierda, menú a la derecha y el botón de llamada a la acción en la esquina inferior derecha del recorrido.", noShuffle:false },
  { concept_id:"diw_u1_q13", unit:1, question:"¿Qué es una 'User Persona' en diseño UX?", options:["El usuario que compra la licencia, concepto diferente al que se describe en esta pregunta","Un arquetipo ficticio pero realista basado en datos de investigación que representa a un segmento clave del público objetivo, incluyendo metas, frustraciones y hábitos","La foto de perfil del programador, concepto que se aplica en un contexto distinto","Un bot automatizado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ayuda a todo el equipo a tomar decisiones de diseño orientadas a personas reales en lugar de basarse en preferencias personales subjetivas.", noShuffle:false },
  { concept_id:"diw_u1_q14", unit:1, question:"¿Qué es un 'Customer Journey Map' (Mapa del Viaje del Usuario)?", options:["Un mapa GPS del cliente, concepto diferente al que se describe en esta pregunta","Una representación visual que ilustra los pasos, puntos de contacto (touchpoints), emociones y barreras que experimenta un usuario al interactuar con el producto para alcanzar un objetivo","El organigrama de la empresa, concepto que se aplica en un contexto distinto","La ruta de los paquetes en la red, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Permite identificar puntos de fricción (pain points) y oportunidades de mejora a lo largo de todo el ciclo de vida del cliente.", noShuffle:false },
  { concept_id:"diw_u1_q15", unit:1, question:"¿Qué es la 'Carga Cognitiva' y por qué debe minimizarse en una interfaz?", options:["El peso en megabytes de los scripts, concepto diferente al que se describe en esta pregunta","El esfuerzo mental y memoria de trabajo que el usuario necesita dedicar para comprender y utilizar la interfaz; una carga alta produce frustración y abandono","El uso de memoria RAM del navegador, concepto que se aplica en un contexto distinto","La cantidad de imágenes cargadas, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Una buena interfaz es invisible: permite al usuario concentrarse en su tarea sin tener que averiguar cómo funciona la herramienta.", noShuffle:false },
  { concept_id:"diw_u1_q16", unit:1, question:"¿Qué es el 'Espacio en Blanco' o 'Espacio Negativo' en diseño visual?", options:["Un error donde falta contenido o imagen, concepto diferente al que se describe en esta pregunta","El espacio intencionadamente vacío alrededor y entre los elementos que permite dar respiro, ordenar la jerarquía y enfocar la atención en lo importante","Una página sin indexar, concepto diferente al que se describe en esta pregunta","Una zona transparente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El espacio negativo es un elemento de diseño fundamental: interfaces atestadas confunden; el espacio genera sofisticación, claridad y legibilidad.", noShuffle:false },
  { concept_id:"diw_u1_q17", unit:1, question:"¿Qué principio de la Gestalt explica que los elementos visualmente cercanos entre sí se perciben como parte de un mismo grupo?", options:["Principio de Proximidad","Principio de Semejanza","Principio de Cierre","Principio de Continuidad"], correct:0, explanation:"El principio de proximidad es la base del espaciado entre etiquetas y campos de formulario o encabezados y sus párrafos correspondientes.", noShuffle:false },
  { concept_id:"diw_u1_q18", unit:1, question:"¿Qué principio de la Gestalt indica que los elementos que comparten características visuales (mismo color, forma o tamaño) se perciben como pertenecientes a la misma categoría?", options:["Principio de Proximidad","Principio de Similitud o Semejanza","Principio de Figura y Fondo","Principio de Destino Común"], correct:1, explanation:"Por ejemplo, usar el mismo color para todos los enlaces o botones primarios comunica al usuario que tienen la misma función interactiva.", noShuffle:false },
  { concept_id:"diw_u1_q19", unit:1, question:"¿Qué es un 'Call to Action' (CTA)?", options:["Una llamada telefónica del soporte, concepto diferente al que se describe en esta pregunta","Un elemento de la interfaz diseñado expresamente para incitar al usuario a realizar una acción clave (ej: 'Comprar ahora', 'Registrarse')","Un mensaje de error, concepto diferente al que se describe en esta pregunta","Un enlace a los términos legales, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los CTAs deben tener jerarquía visual dominante para destacar inmediatamente frente al resto de elementos de la página.", noShuffle:false },
  { concept_id:"diw_u1_q20", unit:1, question:"¿Qué significa el término 'Above the Fold' en diseño web?", options:["El código que va antes de la etiqueta <body>, concepto diferente al que se describe en esta pregunta","La porción superior de la página web que es visible inmediatamente en la pantalla sin necesidad de que el usuario haga scroll hacia abajo","El pie de página (footer), concepto que se aplica en un contexto distinto","El menú desplegable, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Heredado de la prensa escrita, el contenido 'above the fold' capta la primera impresión y debe comunicar de inmediato el valor de la web.", noShuffle:false },
  { concept_id:"diw_u1_q21", unit:1, question:"¿Qué es el enfoque de diseño 'Mobile-First' propuesto por Luke Wroblewski?", options:["Crear apps nativas únicamente, concepto diferente al que se describe en esta pregunta","Diseñar la interfaz pensando primero en las restricciones y necesidades de las pantallas móviles (pantalla reducida, interacción táctil, ancho de banda) y escalar progresivamente hacia ordenadores de escritorio","Prohibir el acceso desde ordenadores, concepto diferente al que se describe en esta pregunta","Usar solo tipografías pequeñas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Obliga a priorizar el contenido esencial y descartar elementos superfluos, creando productos más limpios y eficientes.", noShuffle:false },
  { concept_id:"diw_u1_q22", unit:1, question:"¿Qué es la 'Regla de los Tres Clics' en usabilidad?", options:["Hacer clic tres veces para abrir un enlace es una accion que no define correctamente este concepto","Una regla empírica clásica que sugiere que cualquier información clave de una web debería poder encontrarse en un máximo de tres clics desde la página principal","Un atajo de teclado, concepto diferente al que se describe en esta pregunta","Un gesto táctil, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Aunque la investigación moderna prioriza la claridad del rastro de navegación (information scent) sobre el número exacto de clics, subraya la importancia de jerarquías poco profundas.", noShuffle:false },
  { concept_id:"diw_u1_q23", unit:1, question:"¿Qué es una 'Miga de Pan' (Breadcrumb) en navegación web?", options:["Restos de cookies en el disco, concepto diferente al que se describe en esta pregunta","Un elemento de navegación secundario que muestra al usuario la ruta jerárquica de páginas desde el inicio hasta su ubicación actual","Un tipo de notificación flotante, concepto diferente al que se describe en esta pregunta","Un buscador interno, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite al usuario situarse contextualmente en la estructura del sitio y retroceder a niveles superiores con un solo clic.", noShuffle:false },
  { concept_id:"diw_u1_q24", unit:1, question:"¿Qué es el 'Affordance' (Afording / Capacidad percibida) en diseño de interfaces?", options:["El precio de la licencia de software, que puede confundirse con este termino en contabilidad general","Las propiedades visuales de un objeto que comunican intuitivamente al usuario cómo debe interactuar con él","La velocidad de carga del servidor, concepto que se aplica en un contexto distinto","La resolución de la pantalla, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Un mal affordance genera confusión (ej: un botón que parece texto plano o un texto plano que parece un botón clicable).", noShuffle:false },
  { concept_id:"diw_u1_q25", unit:1, question:"¿Qué es un 'Dark Pattern' (Patrón Oscuro) en diseño de interfaces?", options:["El modo oscuro (Dark Mode) de una web, concepto diferente al que se describe en esta pregunta","Una interfaz deliberadamente diseñada para engañar, manipular o coaccionar al usuario a tomar decisiones que benefician a la empresa pero perjudican al usuario","Una página con fondo negro, concepto diferente al que se describe en esta pregunta","Un fallo de accesibilidad por falta de luz, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los patrones oscuros están siendo progresivamente sancionados por normativas como la Ley de Servicios Digitales (DSA) de la UE.", noShuffle:false },
  { concept_id:"diw_u1_q26", unit:1, question:"¿Qué es la 'Consistencia' en el diseño de interfaces según las heurísticas de Nielsen?", options:["Que todos los archivos pesen lo mismo, concepto diferente al que se describe en esta pregunta","Que los mismos elementos, botones, terminología e interacciones funcionen y luzcan de la misma manera a lo largo de toda la aplicación y sigan las normas de la plataforma","Que la base de datos sea relacional, concepto diferente al que se describe en esta pregunta","Que el servidor no se caiga, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La consistencia reduce drásticamente el aprendizaje: una vez que el usuario aprende a usar un componente en una pantalla, sabe usarlo en todas.", noShuffle:false },
  { concept_id:"diw_u1_q27", unit:1, question:"¿Qué es la 'Arquitectura de Tres Capas' de la información en comercio electrónico?", options:["Inicio, Carrito y Pago, concepto diferente al que se describe en esta pregunta","Categoría > Subcategoría / Listado de Productos > Ficha de Detalle del Producto","HTML, CSS y JS, concepto diferente al que se describe en esta pregunta","Servidor, BD y Cliente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es la estructura de embudo estándar que guía al comprador desde la exploración amplia hasta la decisión de compra detallada.", noShuffle:false },
  { concept_id:"diw_u1_q28", unit:1, question:"¿Qué herramienta metodológica se utiliza en la fase de 'Empatizar' del Design Thinking?", options:["Entrevistas en profundidad, mapas de empatía y observación directa de usuarios","Escribir código HTML directo, concepto diferente al que se describe en esta pregunta","Realizar pruebas de carga en el servidor, concepto diferente al que se describe en esta pregunta","Diseñar la base de datos, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"El mapa de empatía sintetiza qué dice, hace, piensa y siente el usuario respecto a un problema concreto.", noShuffle:false },
  { concept_id:"diw_u1_q29", unit:1, question:"¿Qué es un 'Empty State' (Estado Vacío) en una interfaz?", options:["Una página sin CSS, concepto diferente al que se describe en esta pregunta","La pantalla o componente que se muestra cuando no hay datos disponibles (ej","Un formulario en blanco para rellenar, concepto diferente al que se describe en esta pregunta","Un error 404, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Un buen empty state educa y motiva la acción mediante ilustraciones amigables y llamadas a la acción directas.", noShuffle:false },
  { concept_id:"diw_u1_q30", unit:1, question:"¿Qué es el 'Onboarding' en una aplicación web?", options:["El proceso de cobro con tarjeta, concepto que se aplica en un contexto distinto","El proceso guiado de bienvenida e introducción inicial que ayuda a los nuevos usuarios a comprender el valor del producto y dar sus primeros pasos de forma exitosa","El apagado del servidor, concepto diferente al que se describe en esta pregunta","La carga del favicon, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Un onboarding fluido reduce la tasa de abandono prematuro (churn) tras el registro.", noShuffle:false },
  { concept_id:"diw_u1_q31", unit:1, question:"¿Qué es el 'Microcopy' en diseño UX?", options:["Texto con letra muy pequeña e ilegible, concepto diferente al que se describe en esta pregunta","Las frases cortas, etiquetas, textos de ayuda, mensajes de error y textos en botones que guían al usuario en puntos clave de la interacción","Comentarios en el código CSS, concepto diferente al que se describe en esta pregunta","Textos legales de términos y condiciones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Un microcopy empático y claro (ej: 'No te cobraremos nada ahora') disipa dudas y reduce la fricción en formularios.", noShuffle:false },
  { concept_id:"diw_u1_q32", unit:1, question:"¿Qué es un 'Modal' o ventana modal en diseño de interfaces?", options:["Una ventana del sistema operativo, concepto diferente al que se describe en esta pregunta","Un elemento de diálogo superpuesto sobre la página principal que bloquea la interacción con el resto de la interfaz hasta que el usuario realiza una acción o lo descarta","Un menú lateral permanente, concepto diferente al que se describe en esta pregunta","Un mensaje en la barra de estado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Debe usarse con moderación únicamente para acciones críticas o confirmaciones destructivas, ya que interrumpe el flujo de trabajo.", noShuffle:false },
  { concept_id:"diw_u1_q33", unit:1, question:"¿Qué es el 'Progressive Disclosure' (Divulgación Progresiva)?", options:["Publicar el código poco a poco, concepto diferente al que se describe en esta pregunta","Una técnica de diseño que muestra solo la información necesaria e indispensable al inicio, ofreciendo opciones avanzadas o detalles secundarios solo bajo demanda del usuario","Actualizar la web cada semana, concepto diferente al que se describe en esta pregunta","Subir archivos por partes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Reduce la sobrecarga inicial manteniendo la interfaz limpia sin sacrificar la profundidad de configuración para usuarios avanzados.", noShuffle:false },
  { concept_id:"diw_u1_q34", unit:1, question:"¿Qué es el 'Efecto Halo' en la percepción estética de una interfaz?", options:["Un brillo alrededor de las imágenes, concepto diferente al que se describe en esta pregunta","La tendencia psicológica de los usuarios a asumir que una aplicación atractiva y visualmente pulida es también más fácil de usar, más rápida y más segura (Aesthetic-Usability Effect)","Un fallo en la tarjeta gráfica, concepto diferente al que se describe en esta pregunta","Un tipo de gradiente de CSS, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El diseño estético excelente predispone positivamente al usuario y lo hace más tolerante ante pequeños fallos de funcionamiento.", noShuffle:false },
  { concept_id:"diw_u1_q35", unit:1, question:"¿Qué es un 'Skeleton Screen' o pantalla esqueleto?", options:["Una página web con temática de Halloween, concepto diferente al que se describe en esta pregunta","Una versión simplificada en gris de la estructura de la página con siluetas que se muestra mientras se cargan los datos reales, creando la percepción psicológica de menor tiempo de espera que un spinner","Un fallo de carga del DOM, concepto diferente al que se describe en esta pregunta","El código HTML sin etiquetas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Frecuentemente utilizado en aplicaciones como YouTube, Facebook o LinkedIn para mejorar la percepción de velocidad.", noShuffle:false },
  { concept_id:"diw_u1_q36", unit:1, question:"¿Qué papel desempeña el 'Feedback' inmediato en un formulario interactivo?", options:["Ralentizar el envío, concepto diferente al que se describe en esta pregunta","Informar al usuario al instante de si los datos introducidos son válidos o erróneos (validación inline) antes de que pulse el botón final de enviar","Recargar toda la página, concepto diferente al que se describe en esta pregunta","Enviar correos automáticos es una accion que no define correctamente este concepto"], correct:1, explanation:"La validación inline con mensajes claros evita la frustración de rellenar formularios largos y verlos fallar al final.", noShuffle:false },
  { concept_id:"diw_u1_q37", unit:1, question:"¿Qué es la técnica de 'Crazy Eights' en talleres de Design Sprint?", options:["Un juego de naipes de mesa, concepto diferente al que se describe en esta pregunta","Un ejercicio rápido de ideación donde cada participante esboza 8 ideas distintas de interfaz en 8 minutos doblando un folio en 8 cuadrantes","Ocho horas de programación continua, concepto diferente al que se describe en esta pregunta","Una tipografía de 8 puntos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Fuerza al cerebro a superar las primeras ideas obvias y explorar soluciones innovadoras con rapidez.", noShuffle:false },
  { concept_id:"diw_u1_q38", unit:1, question:"¿Qué es el 'Bounce Rate' (Tasa de Rebote) en analítica de interfaces web?", options:["El número de veces que rebota una pelota en un juego, concepto que se aplica en un contexto distinto","El porcentaje de visitantes que abandonan el sitio web tras ver únicamente una sola página sin realizar ninguna interacción","La tasa de errores del servidor, concepto que se aplica en un contexto distinto","La velocidad de conexión, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Una tasa de rebote excesiva suele señalar problemas de diseño, contenido irrelevante o tiempos de carga inasumibles.", noShuffle:false },
  { concept_id:"diw_u1_q39", unit:1, question:"¿Qué describe la 'Ley de Miller' en psicología cognitiva aplicada al diseño web?", options:["El número medio de elementos que una persona puede mantener en su memoria de trabajo a corto plazo es de 7 ± 2 elementos","Los menús deben tener 20 enlaces, concepto diferente al que se describe en esta pregunta","El tamaño de los botones debe ser de 7 píxeles, concepto que se aplica en un contexto distinto","El texto debe tener 2 columnas, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Aconseja agrupar la información (chunking) en bloques de 5 a 9 unidades lógicas para no desbordar al usuario.", noShuffle:false },
  { concept_id:"diw_u1_q40", unit:1, question:"¿Qué es un 'Card' (Tarjeta) como patrón de diseño de interfaz?", options:["Una tarjeta de crédito únicamente, concepto diferente al que se describe en esta pregunta","Un contenedor visual rectangular que agrupa información heterogénea pero relacionada (imagen, título, texto y acción) sobre un único tema de forma modular y escaneable","Un archivo comprimido, concepto diferente al que se describe en esta pregunta","Un menú desplegable, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las tarjetas son el bloque modular estrella en diseño responsive por su facilidad para reorganizarse en cuadrículas flexibles.", noShuffle:false },
  { concept_id:"diw_u1_q41", unit:1, question:"¿Qué significa el concepto de 'Mobile Parity'?", options:["Que los móviles tengan precios pares, concepto diferente al que se describe en esta pregunta","Que los usuarios en dispositivos móviles deben tener acceso a las mismas funciones, contenidos y capacidades esenciales que los usuarios en ordenadores de escritorio, sin versiones empobrecidas","Que solo se programe para Android, concepto diferente al que se describe en esta pregunta","Que el código tenga dos versiones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ocultar información o funciones críticas en la versión móvil genera frustración en una web donde más del 60% del tráfico es móvil.", noShuffle:false },
  { concept_id:"diw_u1_q42", unit:1, question:"¿Qué es una heurística de usabilidad de 'Prevención de Errores' frente a 'Recuperación de Errores'?", options:["Son idénticas, concepto diferente al que se describe en esta pregunta","Es mucho mejor diseñar la interfaz para evitar que el error ocurra en primer lugar que presentar un mensaje de error tras el fallo","Ignorar los errores, concepto diferente al que se describe en esta pregunta","Corregir errores reiniciando el ordenador, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Diseñar interfaces tolerantes que guíen al usuario evita que cometa equivocaciones irreversibles.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 2 — CSS Avanzado, Flexbox y CSS Grid Layout
  // ════════════════════════════════════════════════════════════════
  { concept_id:"diw_u2_q1", unit:2, question:"¿Cuál es la diferencia fundamental entre el modelo de caja 'content-box' y 'border-box' en CSS?", options:["content-box es solo para texto, concepto diferente al que se describe en esta pregunta","En content-box el width solo aplica al contenido puro (padding y border se suman al tamaño final); en border-box el width incluye el contenido, el padding y el border sin desbordar","border-box no admite márgenes, concepto diferente al que se describe en esta pregunta","No hay diferencia en navegadores modernos, aunque algunos enfoques establecen matices al respecto"], correct:1, explanation:"'box-sizing: border-box;' simplifica los cálculos dimensionales evitando que añadir padding rompa los layouts de la maqueta.", noShuffle:false },
  { concept_id:"diw_u2_q2", unit:2, question:"¿Qué regla universal se aplica habitualmente al inicio de las hojas de estilo para normalizar el modelo de caja en todos los elementos?", options:["* { margin: 0; }","*, *::before, *::after { box-sizing: border-box; }","body { width: 100%; }","div { display: block; }"], correct:1, explanation:"Esta regla universal estandariza el comportamiento de caja en todos los elementos y pseudoelementos.", noShuffle:false },
  { concept_id:"diw_u2_q3", unit:2, question:"¿Cuál es la diferencia arquitectural primordial entre Flexbox y CSS Grid?", options:["Flexbox es más moderno que Grid, concepto diferente al que se describe en esta pregunta","Flexbox es unidimensional (diseñado para distribuir elementos a lo largo de una fila O de una columna); CSS Grid es bidimensional (diseñado para alinear elementos simultáneamente en filas Y columnas)","Grid solo funciona con tablas, concepto diferente al que se describe en esta pregunta","Flexbox no admite responsive, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Flexbox es ideal para componentes internos (barras de navegación, listas, tarjetas); Grid es ideal para el layout estructural de toda la página.", noShuffle:false },
  { concept_id:"diw_u2_q4", unit:2, question:"¿Qué propiedad de Flexbox define la dirección del eje principal (main axis)?", options:["flex-wrap, concepto diferente al que se describe en esta pregunta","flex-direction (row, row-reverse, column, column-reverse)","justify-content, concepto diferente al que se describe en esta pregunta","align-items, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"flex-direction determina si los elementos flexibles fluyen horizontalmente (row, por defecto) o verticalmente (column).", noShuffle:false },
  { concept_id:"diw_u2_q5", unit:2, question:"¿Qué propiedad alinea los elementos a lo largo del eje principal (main axis) en un contenedor Flexbox?", options:["align-items, concepto diferente al que se describe en esta pregunta","justify-content (flex-start, center, space-between, space-around","align-content, concepto diferente al que se describe en esta pregunta","align-self, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"justify-content distribuye el espacio sobrante entre los elementos a lo largo del eje principal.", noShuffle:false },
  { concept_id:"diw_u2_q6", unit:2, question:"¿Qué propiedad alinea los elementos a lo largo del eje transversal (cross axis) en una sola línea de Flexbox?", options:["justify-content, concepto diferente al que se describe en esta pregunta","align-items (stretch, center, flex-start, flex-end, baseline)","align-self, concepto diferente al que se describe en esta pregunta","flex-flow, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"align-items controla la posición perpendicular al eje principal.", noShuffle:false },
  { concept_id:"diw_u2_q7", unit:2, question:"¿Qué propiedad permite a los elementos de un contenedor Flexbox saltar a la línea siguiente si no caben en una sola?", options:["flex-wrap: wrap;","flex-break: on;","flex-flow: multi;","wrap: true;"], correct:0, explanation:"Por defecto flex-wrap es 'nowrap'. Con 'wrap' los elementos desbordan ordenadamente a nuevas filas o columnas.", noShuffle:false },
  { concept_id:"diw_u2_q8", unit:2, question:"¿Qué tres valores componen la propiedad abreviada 'flex: 1 1 auto;' de un elemento flexible hijo?", options:["flex-direction, flex-wrap y flex-align, concepto diferente al que se describe en esta pregunta","flex-grow (capacidad de crecer), flex-shrink (capacidad de encogerse) y flex-basis (tamaño base inicial)","width, height y margin, concepto diferente al que se describe en esta pregunta","top, left y right, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"'flex: 1 1 0px;' permite que el elemento crezca y se encoja proporcionalmente absorbiendo el espacio disponible.", noShuffle:false },
  { concept_id:"diw_u2_q9", unit:2, question:"¿Qué propiedad permite a un elemento hijo individual sobreescribir la alineación en el eje transversal establecida por el contenedor en Flexbox?", options:["align-items","align-self","justify-self","flex-align"], correct:1, explanation:"align-self: center / flex-end permite personalizar la posición de un único hijo independientemente de sus hermanos.", noShuffle:false },
  { concept_id:"diw_u2_q10", unit:2, question:"¿Cómo se define una cuadrícula CSS Grid con tres columnas de igual anchura en el contenedor?", options:["grid-columns: 3;, concepto diferente al que se describe en esta pregunta","grid-template-columns: 1fr 1fr 1fr; (o repeat(3, 1fr);)","columns: 3;, concepto diferente al que se describe en esta pregunta","display-grid: 33%;, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La unidad de fracción 'fr' representa una porción del espacio libre disponible dentro del contenedor grid.", noShuffle:false },
  { concept_id:"diw_u2_q11", unit:2, question:"¿Qué propiedad establece el espaciado entre filas y columnas tanto en CSS Grid como en Flexbox moderno?", options:["margin-between, concepto diferente al que se describe en esta pregunta","gap (o row-gap y column-gap)","grid-spacing, concepto diferente al que se describe en esta pregunta","padding-cells, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"gap: 20px; aplica un canal o medianil limpio entre elementos sin tener que lidiar con márgenes en los bordes exteriores.", noShuffle:false },
  { concept_id:"diw_u2_q12", unit:2, question:"¿Qué función de CSS Grid permite crear cuadrículas totalmente responsivas sin necesidad de media queries ajustando el número de columnas automáticamente?", options:["grid-template-columns: repeat(auto-fit, minmax(250px, 1fr))","grid-columns: auto-responsive;, concepto diferente al que se describe en esta pregunta","grid-fluid: true;, concepto diferente al que se describe en esta pregunta","display: flex-grid;, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"auto-fit o auto-fill junto con minmax() empaqueta tantas columnas de mínimo 250px como quepan y las expande para llenar la fila.", noShuffle:false },
  { concept_id:"diw_u2_q13", unit:2, question:"¿Qué propiedad de CSS Grid permite nombrar áreas visuales de la maqueta usando una representación gráfica en forma de plantilla textual?", options:["grid-template-areas","grid-layout-map","grid-regions","grid-map"], correct:0, explanation:"grid-template-areas: 'header header' 'sidebar main' 'footer footer'; permite asociar hijos con grid-area: header.", noShuffle:false },
  { concept_id:"diw_u2_q14", unit:2, question:"¿Cómo se declara y se utiliza una variable nativa (Custom Property) en CSS?", options:["$color: red; color: $color;, concepto diferente al que se describe en esta pregunta","--color-primario: #007bff; color: var(--color-primario)","@color = blue; color: @color;, concepto diferente al que se describe en esta pregunta","let color = 'green'; color: get(color);"], correct:1, explanation:"Las variables CSS inician con dos guiones (--nombre) y se leen mediante la función var(--nombre, valorFallback).", noShuffle:false },
  { concept_id:"diw_u2_q15", unit:2, question:"¿Dónde se declaran convencionalmente las variables CSS globales para que estén disponibles en todo el documento?", options:["En la etiqueta <head>","En la pseudoclase :root","En el selector body únicamente","En un archivo .json"], correct:1, explanation:":root apunta a la raíz del documento (equivalente a <html> pero con mayor especificidad), garantizando alcance global en cascada.", noShuffle:false },
  { concept_id:"diw_u2_q16", unit:2, question:"¿Cuál es la sintaxis correcta de una Media Query para aplicar estilos exclusivamente a pantallas con ancho mínimo de 768 píxeles?", options:["@media (min-width: 768px) { ... }","@screen min 768px { ... }","@media width >= 768px { ... } (admitida en CSS moderno Level 4)","Tanto a como c son sintaxis válidas"], correct:3, explanation:"La sintaxis clásica es (min-width: 768px), y Media Queries Level 4 estandariza los operadores matemáticos (width >= 768px).", noShuffle:false },
  { concept_id:"diw_u2_q17", unit:2, question:"¿Por qué se utilizan Media Queries con 'min-width' en lugar de 'max-width' en la metodología Mobile-First?", options:["Porque es obligatorio en CSS, concepto diferente al que se describe en esta pregunta","Para definir los estilos base móviles sin media query y añadir reglas que enriquecen progresivamente la interfaz conforme el ancho de pantalla aumenta hacia tablets y escritorios","Porque max-width está deprecado, concepto diferente al que se describe en esta pregunta","Para que las fuentes se vean más grandes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El diseño progresa de lo pequeño a lo grande mediante sobreescritura natural en cascada.", noShuffle:false },
  { concept_id:"diw_u2_q18", unit:2, question:"¿Cuál es la diferencia entre las unidades relativas 'em' y 'rem' en CSS?", options:["em es para márgenes y rem para texto, concepto diferente al que se describe en esta pregunta","'rem' es relativo al tamaño de fuente del elemento raíz (<html>","em es absoluto y rem relativo, concepto diferente al que se describe en esta pregunta","rem no funciona en Chrome, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"rem previene el 'problema del escalado compuesto' de em (donde listas anidadas crecen o decrecen descontroladamente).", noShuffle:false },
  { concept_id:"diw_u2_q19", unit:2, question:"¿Qué representan las unidades de viewport 'vw', 'vh', 'vmin' y 'vmax'?", options:["Píxeles físicos del monitor, concepto diferente al que se describe en esta pregunta","Porcentajes del ancho (vw) o alto (vh) del área visible del navegador (1vw = 1% del ancho del viewport)","Velocidad de refresco de pantalla, concepto diferente al que se describe en esta pregunta","Volumen de la imagen, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"100vw y 100vh ocupan el 100% exacto de la ventana del navegador.", noShuffle:false },
  { concept_id:"diw_u2_q20", unit:2, question:"¿Qué problema resolvieron las nuevas unidades de viewport dinámica 'dvh', 'svh' y 'lvh' en dispositivos móviles?", options:["El color de la pantalla, concepto que se aplica en un contexto distinto","Las barras de dirección e interfaz del navegador móvil que aparecen y desaparecen al hacer scroll alterando la altura real utilizable de 100vh","El brillo del móvil, concepto diferente al que se describe en esta pregunta","La orientación apaisada, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"dvh (dynamic vh) recalcula la altura real conforme la barra de navegación del navegador móvil se expande o colapsa.", noShuffle:false },
  { concept_id:"diw_u2_q21", unit:2, question:"¿Qué función matemática de CSS permite restringir un valor entre un mínimo, un valor preferido relativo y un máximo?", options:["minmax(min, max)","clamp(min, preferido, max)","limit(min, max)","bound(min, pref, max)"], correct:1, explanation:"clamp(1rem, 2.5vw, 2rem) crea tipografías fluidas que crecen con la pantalla sin volverse diminutas en móviles ni gigantescas en monitores 4K.", noShuffle:false },
  { concept_id:"diw_u2_q22", unit:2, question:"¿Qué función de CSS calcula dinámicamente valores combinando diferentes unidades (ej: porcentajes y píxeles)?", options:["calc(100% - 20px)","math(100% - 20px)","compute()","eval()"], correct:0, explanation:"calc() realiza sumas, restas, multiplicaciones y divisiones en tiempo de renderizado respetando espacios alrededor de operadores.", noShuffle:false },
  { concept_id:"diw_u2_q23", unit:2, question:"¿Cómo se calcula la especificidad de un selector CSS y cuál tiene mayor peso?", options:["Por el número de letras del selector, concepto diferente al que se describe en esta pregunta","Mediante una tupla (Inline, IDs, Clases/Atributos/Pseudoclases","Todos los selectores pesan exactamente igual","El que esté escrito más arriba, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Un ID (#menu, peso 0,1,0,0) vence a diez clases combinadas (.btn.primary, peso 0,0,2,0).", noShuffle:false },
  { concept_id:"diw_u2_q24", unit:2, question:"¿Por qué se debe evitar el uso indiscriminado de la declaración '!important' en CSS?", options:["Porque rompe la sintaxis en Firefox, concepto diferente al que se describe en esta pregunta","Porque destruye el flujo natural de la cascada y la especificidad","Porque ralentiza el navegador en 10 segundos, concepto diferente al que se describe en esta pregunta","Porque solo funciona en etiquetas <div>, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"!important debe reservarse únicamente para clases utilitarias de choque o sobreescritura de estilos incrustados de widgets externos.", noShuffle:false },
  { concept_id:"diw_u2_q25", unit:2, question:"¿Qué es una 'Container Query' (@container) en CSS moderno frente a una Media Query (@media)?", options:["No hay diferencia, aunque algunos enfoques establecen matices al respecto","La Media Query evalúa el ancho de todo el viewport del navegador","Container Queries solo funcionan en Docker, concepto diferente al que se describe en esta pregunta","Son para el color del fondo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite crear componentes verdaderamente modulares que adaptan su layout según el espacio disponible en la columna donde estén alojados.", noShuffle:false },
  { concept_id:"diw_u2_q26", unit:2, question:"¿Qué pseudoclase de CSS permite seleccionar un elemento padre basándose en los hijos o descendientes que contiene?", options:[":parent, concepto diferente al que se describe en esta pregunta",":has() (ej: article:has(img))",":contains(), concepto diferente al que se describe en esta pregunta",":with(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:":has() es el revolucionario selector de padre en CSS moderno, permitiendo cambiar el diseño del contenedor si contiene un elemento específico.", noShuffle:false },
  { concept_id:"diw_u2_q27", unit:2, question:"¿Qué valor de la propiedad 'position' mantiene a un elemento fijo dentro de su contenedor padre solo mientras este esté visible al hacer scroll?", options:["position: fixed;","position: absolute;","position: sticky;","position: relative;"], correct:2, explanation:"sticky actúa como 'relative' hasta que alcanza un umbral de scroll especificado (ej: top: 0), momento en que se comporta como 'fixed' dentro de su padre.", noShuffle:false },
  { concept_id:"diw_u2_q28", unit:2, question:"¿Qué propiedad de CSS controla cómo se comporta una imagen o vídeo dentro de las dimensiones fijadas de su contenedor?", options:["object-fit (contain, cover, fill, none, scale-down)","image-scale, concepto diferente al que se describe en esta pregunta","fit-image, concepto diferente al que se describe en esta pregunta","background-size, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"object-fit: cover; hace que la imagen llene el espacio disponible recortando los bordes sin deformar su relación de aspecto original.", noShuffle:false },
  { concept_id:"diw_u2_q29", unit:2, question:"¿Qué propiedad de CSS define la relación entre la anchura y la altura de un elemento para evitar saltos de layout al cargar imágenes (CLS)?", options:["aspect-ratio (ej: aspect-ratio: 16 / 9;)","ratio, concepto diferente al que se describe en esta pregunta","proportion, concepto diferente al que se describe en esta pregunta","size-ratio, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"aspect-ratio reserva el espacio visual exacto antes de que el recurso termine de descargarse, previniendo el Cumulative Layout Shift.", noShuffle:false },
  { concept_id:"diw_u2_q30", unit:2, question:"¿Qué es el efecto visual 'Glassmorphism' en CSS y qué propiedad es indispensable para lograrlo?", options:["Un marco de cristal roto, concepto diferente al que se describe en esta pregunta","Un estilo que imita vidrio esmerilado translúcido combinando fondo semitransparente con 'backdrop-filter: blur(10px);' y bordes sutiles","Una imagen 3D, concepto diferente al que se describe en esta pregunta","Un filtro de escala de grises, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"backdrop-filter difumina el contenido que se encuentra detrás del elemento creando una sensación de profundidad premium.", noShuffle:false },
  { concept_id:"diw_u2_q31", unit:2, question:"¿Cómo se crea un degradado lineal suave que va de azul a púrpura en CSS?", options:["color: gradient(blue, purple);, concepto diferente al que se describe en esta pregunta","background: linear-gradient(to right, #007bff, #6f42c1)","filter: gradient;, concepto diferente al que se describe en esta pregunta","border-gradient: linear;, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"linear-gradient acepta ángulos (45deg) o direcciones (to bottom, to right) y múltiples paradas de color con porcentajes.", noShuffle:false },
  { concept_id:"diw_u2_q32", unit:2, question:"¿Qué propiedad de CSS aplica sombras realistas con desplazamiento horizontal, vertical, desenfoque, propagación y color?", options:["shadow, concepto diferente al que se describe en esta pregunta","box-shadow (ej: 0 4px 6px -1px rgba(0, 0, 0, 0.1))","border-shadow, concepto diferente al que se describe en esta pregunta","drop-shadow, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"box-shadow permite sombras múltiples separadas por comas para simular capas de elevación visual.", noShuffle:false },
  { concept_id:"diw_u2_q33", unit:2, question:"¿Qué propiedad controla el truncamiento de texto en una sola línea añadiendo puntos suspensivos (...) cuando desborda?", options:["text-overflow: ellipsis; junto con white-space: nowrap; y overflow: hidden","text-cut: true;, concepto diferente al que se describe en esta pregunta","overflow: dots;, concepto diferente al que se describe en esta pregunta","truncate: on;, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Para que funcione text-overflow: ellipsis, es imprescindible fijar el contenedor con overflow: hidden y evitar saltos con white-space: nowrap.", noShuffle:false },
  { concept_id:"diw_u2_q34", unit:2, question:"¿Qué propiedad moderna de CSS permite truncar texto a un número específico de líneas (ej: 3 líneas) añadiendo puntos suspensivos?", options:["line-clamp: 3; (o -webkit-line-clamp: 3;)","max-lines: 3;, concepto diferente al que se describe en esta pregunta","text-limit: 3;, concepto diferente al que se describe en esta pregunta","lines: 3;, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"-webkit-line-clamp: 3 junto con display: -webkit-box y -webkit-box-orient: vertical trunca párrafos multilínea elegantemente.", noShuffle:false },
  { concept_id:"diw_u2_q35", unit:2, question:"¿Qué propiedad CSS evita que un elemento intercepte clics o eventos del ratón permitiendo que pasen al elemento situado detrás?", options:["cursor: none;","pointer-events: none;","user-select: none;","click-through: true;"], correct:1, explanation:"pointer-events: none hace que el elemento sea 'invisible' a los eventos de puntero (útil para iconos decorativos sobre inputs).", noShuffle:false },
  { concept_id:"diw_u2_q36", unit:2, question:"¿Qué propiedad de CSS previene que el usuario pueda seleccionar texto al hacer doble clic o arrastrar?", options:["pointer-events: none;","user-select: none;","text-select: false;","selectable: no;"], correct:1, explanation:"user-select: none es ideal en botones y elementos de UI para evitar selecciones accidentales de texto al interactuar rápidamente.", noShuffle:false },
  { concept_id:"diw_u2_q37", unit:2, question:"¿Qué Media Feature de CSS permite detectar si el usuario ha configurado el modo oscuro en su sistema operativo?", options:["@media (prefers-color-scheme: dark) { ... }","@media (theme: dark)","@media (dark-mode: on)","@media (color: black)"], correct:0, explanation:"Permite alternar paletas de color y variables CSS automáticamente según las preferencias de accesibilidad del sistema.", noShuffle:false },
  { concept_id:"diw_u2_q38", unit:2, question:"¿Qué Media Feature de CSS permite detectar si el usuario ha solicitado reducir las animaciones por problemas vestibulares o cinetosis?", options:["@media (prefers-reduced-motion: reduce) { ... }","@media (no-animations: true)","@media (motion: slow)","@media (static-ui: on)"], correct:0, explanation:"Esencial para la accesibilidad: desactiva transiciones y rebotes agresivos para usuarios propensos al mareo.", noShuffle:false },
  { concept_id:"diw_u2_q39", unit:2, question:"¿Qué Media Feature de CSS permite distinguir si el dispositivo principal de entrada es táctil (coarse) o un ratón de precisión (fine)?", options:["@media (pointer: coarse) o @media (hover: hover)","@media (touch: true), concepto diferente al que se describe en esta pregunta","@media (device: mobile), concepto diferente al que se describe en esta pregunta","@media (mouse: active), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"pointer: coarse indica interacción con dedos, recomendando ampliar las zonas interactivas a un mínimo de 44x44px.", noShuffle:false },
  { concept_id:"diw_u2_q40", unit:2, question:"¿Qué propiedad CSS controla la suavidad del desplazamiento al navegar a través de enlaces ancla internos (#seccion)?", options:["scroll-behavior: smooth;","scroll-mode: soft;","scroll-speed: slow;","smooth-scroll: on;"], correct:0, explanation:"scroll-behavior: smooth en el elemento <html> produce un desplazamiento continuo y fluido en lugar de un salto brusco instantáneo.", noShuffle:false },
  { concept_id:"diw_u2_q41", unit:2, question:"¿Qué propiedad permite crear carruseles y listas táctiles que se 'enganchan' magnéticamente en cada tarjeta al soltar el dedo?", options:["CSS Scroll Snap (scroll-snap-type y scroll-snap-align)","touch-slider: on;, concepto diferente al que se describe en esta pregunta","carousel-snap: true;, concepto diferente al que se describe en esta pregunta","scroll-lock: item;, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"scroll-snap-type: x mandatory; en el padre y scroll-snap-align: start; en los hijos implementa carruseles nativos sin JavaScript.", noShuffle:false },
  { concept_id:"diw_u2_q42", unit:2, question:"¿Qué selector CSS selecciona todos los elementos 'p' que son hermanos inmediatos situados justo después de un 'h2'?", options:["h2 > p, concepto diferente al que se describe en esta pregunta","h2 ~ p, concepto diferente al que se describe en esta pregunta","h2 + p (Selector de hermano adyacente)","h2 p, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"h2 + p aplica solo al primer párrafo inmediatamente contiguo. h2 ~ p aplica a todos los párrafos hermanos posteriores.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 3 — Usabilidad y Accesibilidad Web (WCAG, WAI-ARIA)
  // ════════════════════════════════════════════════════════════════
  { concept_id:"diw_u3_q1", unit:3, question:"¿Qué significan las siglas WCAG y qué entidad internacional las publica?", options:["Web Creator Action Group; publicada por Google, concepto diferente al que se describe en esta pregunta","Web Content Accessibility Guidelines (Pautas de Accesibilidad para el Contenido Web); publicadas por el W3C a través de la WAI","World Computing Alliance Guide; publicada por la ISO, concepto diferente al que se describe en esta pregunta","Web Consortium Accessibility Grade; publicada por Mozilla, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las WCAG son el estándar técnico mundial de referencia para hacer el contenido web accesible a personas con discapacidad.", noShuffle:false },
  { concept_id:"diw_u3_q2", unit:3, question:"¿Cuáles son los cuatro principios fundamentales (POUR) en los que se estructuran las WCAG?", options:["Rápido, Barato, Bonito y Seguro, concepto diferente al que se describe en esta pregunta","Perceptible, Operable, Comprensible (Understandable) y Robusto","Público, Online, Universal y Responsivo, concepto diferente al que se describe en esta pregunta","Planificar, Organizar, Unificar y Renderizar"], correct:1, explanation:"POUR: la información debe ser Perceptible por los sentidos, Operable en la interfaz, Comprensible en su uso y Robusta ante tecnologías de asistencia.", noShuffle:false },
  { concept_id:"diw_u3_q3", unit:3, question:"¿Cuáles son los tres niveles de conformidad sucesivos definidos en las WCAG?", options:["Nivel 1, Nivel 2 y Nivel 3, concepto diferente al que se describe en esta pregunta","Nivel A (requisito mínimo indispensable), Nivel AA (estándar legal exigido habitualmente) y Nivel AAA (máximo nivel de accesibilidad especializada)","Bronce, Plata y Oro, concepto diferente al que se describe en esta pregunta","Básico, Avanzado y Profesional, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El Nivel AA es el objetivo legal vinculante exigido por directivas europeas (EN 301 549) y leyes de accesibilidad para sitios públicos y corporativos.", noShuffle:false },
  { concept_id:"diw_u3_q4", unit:3, question:"¿Cuál es la relación de contraste de color mínima exigida por WCAG 2.1 nivel AA para texto de tamaño normal respecto a su fondo?", options:["2:1","3:1","4.5:1","7:1"], correct:2, explanation:"4.5:1 para texto normal (<18pt o <14pt negrita). Para texto grande (>=18pt o >=14pt negrita) el ratio mínimo es 3:1.", noShuffle:false },
  { concept_id:"diw_u3_q5", unit:3, question:"¿Cuál es el ratio de contraste exigido para cumplir con el nivel más estricto AAA para texto normal?", options:["4.5:1","7:1","10:1","15:1"], correct:1, explanation:"El nivel AAA eleva la exigencia a 7:1 para texto estándar y 4.5:1 para texto de gran tamaño.", noShuffle:false },
  { concept_id:"diw_u3_q6", unit:3, question:"¿Por qué es una grave violación de accesibilidad transmitir información únicamente a través del color (ej: campos obligatorios solo en rojo)?", options:["Porque el rojo es agresivo, concepto diferente al que se describe en esta pregunta","Porque los usuarios con daltonismo, baja visión o que usen monocromo no podrán distinguir qué elementos están destacados o con error","Porque el CSS pesa más, concepto diferente al que se describe en esta pregunta","Porque las pantallas gastan más energía, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Criterio WCAG 1.4.1: el color debe complementarse siempre con un indicador secundario (iconos, texto explicativo, asteriscos, subrayado).", noShuffle:false },
  { concept_id:"diw_u3_q7", unit:3, question:"¿Qué función cumple el atributo 'alt' en la etiqueta <img>?", options:["Un título que aparece al pasar el ratón, concepto diferente al que se describe en esta pregunta","Proporcionar una descripción textual alternativa del contenido o función de la imagen leída por lectores de pantalla y mostrada si la imagen no carga","El ancho de la imagen, concepto que se aplica en un contexto distinto","El enlace de descarga, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Si la imagen es puramente decorativa, se debe dejar alt=\"\" vacío para que los lectores de pantalla la ignoren y no interrumpan la lectura.", noShuffle:false },
  { concept_id:"diw_u3_q8", unit:3, question:"¿Qué significan las siglas WAI-ARIA?", options:["Web Advanced Interface - Audio Real Interface Application, concepto diferente al que se describe en esta pregunta","Accessible Rich Internet Applications Suite de la Web Accessibility Initiative (W3C)","Web Artificial Intelligence Accessible Architecture, concepto diferente al que se describe en esta pregunta","Wireless Accessibility Resource Internet, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"WAI-ARIA define roles, estados y propiedades semánticas adicionales para hacer accesibles componentes web dinámicos complejos.", noShuffle:false },
  { concept_id:"diw_u3_q9", unit:3, question:"¿Cuál es la 'Primera Regla de ARIA' formulada por el W3C?", options:["Usar ARIA en todos los elementos HTML, concepto diferente al que se describe en esta pregunta","Si puedes usar un elemento nativo de HTML con la semántica y comportamiento requeridos","ARIA solo funciona en Chrome, concepto diferente al que se describe en esta pregunta","ARIA es obligatoria en formularios, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los elementos nativos ya tienen soporte accesible, foco y control por teclado implementado de serie por los navegadores de forma robusta.", noShuffle:false },
  { concept_id:"diw_u3_q10", unit:3, question:"¿Para qué sirve el atributo 'aria-label'?", options:["Para cambiar la tipografía, concepto diferente al que se describe en esta pregunta","Para proporcionar una etiqueta textual accesible directa a un elemento interactivo que no tiene texto visible en pantalla","Para ordenar listas, concepto diferente al que se describe en esta pregunta","Para traducir texto, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"<button aria-label=\"Buscar en la tienda\"><svg>...</svg></button> garantiza que el lector de pantalla anuncie la función del botón.", noShuffle:false },
  { concept_id:"diw_u3_q11", unit:3, question:"¿Para qué sirve el atributo 'aria-labelledby'?", options:["Para enlazar estilos CSS, concepto diferente al que se describe en esta pregunta","Para indicar el ID de otro elemento de la página cuyo texto sirve como etiqueta accesible para el elemento actual","Para cambiar el color de una etiqueta, concepto diferente al que se describe en esta pregunta","Para crear listas numeradas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite reutilizar encabezados o párrafos visibles existentes como el nombre accesible del componente.", noShuffle:false },
  { concept_id:"diw_u3_q12", unit:3, question:"¿Para qué sirve el atributo 'aria-hidden=\"true\"'?", options:["Para ocultar el elemento visualmente de la pantalla, concepto diferente al que se describe en esta pregunta","Para ocultar el elemento a las tecnologías de asistencia (lectores de pantalla) sin ocultarlo visualmente (útil para iconos decorativos duplicados)","Para borrar el nodo del DOM, concepto diferente al que se describe en esta pregunta","Para cerrar sesiones, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evita redundancias auditivas molestas cuando un icono visual complementa a un texto ya descriptivo contiguo.", noShuffle:false },
  { concept_id:"diw_u3_q13", unit:3, question:"¿Qué es una 'Región Viva' de ARIA (aria-live=\"polite\" / \"assertive\")?", options:["Un vídeo en directo, concepto diferente al que se describe en esta pregunta","Una zona del documento que informa automáticamente al lector de pantalla de cambios dinámicos ocurridos en su contenido sin necesidad de recargar la página","Una animación infinita, concepto diferente al que se describe en esta pregunta","Un enlace activo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"aria-live=\"polite\" espera a que el usuario termine de hablar; \"assertive\" interrumpe de inmediato para emergencias críticas.", noShuffle:false },
  { concept_id:"diw_u3_q14", unit:3, question:"¿Qué es el 'Foco de Teclado' (Keyboard Focus) y por qué NUNCA debe eliminarse con 'outline: none;' sin alternativa visual?", options:["Un virus de teclado, concepto diferente al que se describe en esta pregunta","El indicador visual que resalta qué elemento interactivo tiene actualmente la atención del sistema al navegar con el tabulador; eliminarlo deja ciegos a los usuarios de teclado","El brillo de las teclas, concepto que se aplica en un contexto distinto","Un atajo de teclado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los usuarios con movilidad reducida o que no usan ratón necesitan ver exactamente dónde se encuentra el cursor de navegación.", noShuffle:false },
  { concept_id:"diw_u3_q15", unit:3, question:"¿Qué pseudoclase de CSS moderna permite mostrar el contorno de foco SOLO cuando el usuario navega con teclado y ocultarlo al hacer clic con ratón?", options:[":focus, concepto diferente al que se describe en esta pregunta",":focus-visible",":active, concepto diferente al que se describe en esta pregunta",":hover, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:":focus-visible ofrece lo mejor de los dos mundos: accesibilidad total por teclado y estética limpia para usuarios de ratón.", noShuffle:false },
  { concept_id:"diw_u3_q16", unit:3, question:"¿Qué es un enlace 'Skip to Content' (Saltar al contenido principal)?", options:["Un anuncio publicitario, concepto diferente al que se describe en esta pregunta","Un enlace accesible oculto al inicio de la página que se hace visible al pulsar Tabulador y permite a usuarios de teclado saltarse el menú de navegación repetitivo directo al contenido","Un enlace para descargar la web, concepto diferente al que se describe en esta pregunta","Un comando de consola, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evita que un usuario que navega por teclado tenga que presionar la tecla Tabulador 50 veces en cada página para llegar al artículo principal.", noShuffle:false },
  { concept_id:"diw_u3_q17", unit:3, question:"¿Qué significa el valor 'tabindex=\"0\"' aplicado a un elemento HTML?", options:["Que no se puede enfocar, concepto diferente al que se describe en esta pregunta","Que el elemento se inserta en el orden secuencial natural de navegación por teclado en la posición correspondiente a su lugar en el DOM","Que es el primer elemento de la web, concepto diferente al que se describe en esta pregunta","Que se enfoca con el ratón, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Hace que elementos no interactivos por defecto sean enfocables por teclado siguiendo el orden del documento.", noShuffle:false },
  { concept_id:"diw_u3_q18", unit:3, question:"¿Qué significa el valor 'tabindex=\"-1\"'?", options:["Un error de compilación, concepto diferente al que se describe en esta pregunta","Que el elemento puede recibir el foco programáticamente con JavaScript (.focus()), pero NO se puede alcanzar navegando secuencialmente con el Tabulador","Que se enfoca al revés, concepto diferente al que se describe en esta pregunta","Que borra el foco, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Esencial para modales emergentes o mensajes de error dinámicos hacia donde se debe mover el foco por script.", noShuffle:false },
  { concept_id:"diw_u3_q19", unit:3, question:"¿Por qué se desaconseja terminantemente usar valores positivos de tabindex (ej: tabindex=\"1\", tabindex=\"2\")?", options:["Porque no están permitidos en HTML5, concepto diferente al que se describe en esta pregunta","Porque alteran artificialmente el orden natural de tabulación del DOM","Porque desactivan el ratón, concepto diferente al que se describe en esta pregunta","Porque rompen el CSS, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Cualquier elemento con tabindex positivo se enfoca antes que el resto de la página, destrozando la navegación intuitiva.", noShuffle:false },
  { concept_id:"diw_u3_q20", unit:3, question:"¿Qué es un 'Lector de Pantalla' (Screen Reader)?", options:["Un tipo de monitor de ordenador, concepto diferente al que se describe en esta pregunta","Un software de asistencia que interpreta el árbol de accesibilidad del navegador y transmite el contenido y controles mediante síntesis de voz o una línea braille a personas ciegas o con baja visión","Un escáner de códigos de barras, concepto diferente al que se describe en esta pregunta","Un corrector ortográfico, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Lectores populares incluyen NVDA y JAWS (Windows), VoiceOver (Apple iOS/macOS) y TalkBack (Android).", noShuffle:false },
  { concept_id:"diw_u3_q21", unit:3, question:"¿Cuál es la forma correcta y accesible de asociar un texto de etiqueta con su campo de formulario en HTML?", options:["Poner el texto al lado del input sin más, concepto diferente al que se describe en esta pregunta","Usar la etiqueta <label for=\"id_input\">Texto</label> apuntando al id correspondiente del <input id=\"id_input\">","Usar solo el atributo placeholder, concepto diferente al que se describe en esta pregunta","Poner el input dentro de un div, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La asociación explícita 'for/id' permite a los lectores de pantalla anunciar el nombre del campo y amplía el área de clic sobre el texto.", noShuffle:false },
  { concept_id:"diw_u3_q22", unit:3, question:"¿Por qué el atributo 'placeholder' NUNCA debe sustituir a la etiqueta <label>?", options:["Porque es obligatorio poner label en HTML, concepto diferente al que se describe en esta pregunta","Porque el placeholder desaparece al empezar a escribir, tiene bajo contraste por defecto y muchos lectores de pantalla no lo anuncian de forma consistente","Porque solo admite números, concepto diferente al que se describe en esta pregunta","Porque ralentiza el navegador, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El placeholder es una pista complementaria de formato, nunca una etiqueta identificativa del campo.", noShuffle:false },
  { concept_id:"diw_u3_q23", unit:3, question:"¿Cuál es la regla de oro para la jerarquía de encabezados (<h1> a <h6>) en un documento web?", options:["Usarlos según el tamaño de letra deseado, concepto diferente al que se describe en esta pregunta","Mantener una jerarquía estructural lógica sin saltarse niveles y tener un único <h1> representativo por página","Usar solo etiquetas <h3>, concepto diferente al que se describe en esta pregunta","El orden es irrelevante, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los usuarios de lectores de pantalla utilizan los encabezados como una tabla de contenidos interactiva para navegar velozmente entre secciones.", noShuffle:false },
  { concept_id:"diw_u3_q24", unit:3, question:"¿Qué tamaño mínimo de área de interacción táctil (Touch Target Size) recomienda WCAG 2.2 y Google para botones y enlaces en pantallas móviles?", options:["10 x 10 píxeles, concepto diferente al que se describe en esta pregunta","Al menos 44 x 44 píxeles (o 48 x 48 dp) incluyendo el espaciado entre objetivos","100 x 100 píxeles, concepto diferente al que se describe en esta pregunta","No hay tamaño mínimo, aunque algunos enfoques establecen matices al respecto"], correct:1, explanation:"Garantiza que personas con dificultades motoras o dedos grandes puedan pulsar el elemento con precisión sin activar botones adyacentes por error.", noShuffle:false },
  { concept_id:"diw_u3_q25", unit:3, question:"¿Qué es el 'Árbol de Accesibilidad' (Accessibility Tree)?", options:["Una estructura botánica, concepto diferente al que se describe en esta pregunta","Una estructura de datos generada por el navegador en paralelo al DOM que expone roles, estados, propiedades y nombres accesibles a las tecnologías de asistencia","Un árbol de archivos del servidor, concepto diferente al que se describe en esta pregunta","El mapa del sitio XML, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los lectores de pantalla no leen el HTML directamente; leen la información procesada en el Árbol de Accesibilidad.", noShuffle:false },
  { concept_id:"diw_u3_q26", unit:3, question:"¿Qué es una 'Trampa de Foco' (Focus Trap) y cuándo es indispensable implementarla por accesibilidad?", options:["Un virus de teclado, concepto diferente al que se describe en esta pregunta","Confinar el foco de navegación por teclado dentro de una ventana modal activa mientras esté abierta, impidiendo que el usuario navegue accidentalmente por la página de fondo oculta","Un bloqueo del cursor de ratón, concepto diferente al que se describe en esta pregunta","Un fallo del navegador, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Al cerrar el modal con Escape o botón de cierre, el foco debe restituirse al elemento que abrió el modal originalmente.", noShuffle:false },
  { concept_id:"diw_u3_q27", unit:3, question:"¿Por qué se debe evitar el uso de enlaces genéricos con texto 'Haz clic aquí' o 'Leer más'?", options:["Porque es una frase pasada de moda, concepto diferente al que se describe en esta pregunta","Porque fuera de contexto no informan de hacia dónde conduce el enlace ni cuál es su propósito","Porque no tienen enlace, concepto diferente al que se describe en esta pregunta","Porque rompen el SEO únicamente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los textos de enlace deben ser autodescriptivos e informativos por sí mismos (ej: 'Descargar informe anual en PDF').", noShuffle:false },
  { concept_id:"diw_u3_q28", unit:3, question:"¿Qué atributo HTML es obligatorio especificar en la etiqueta raíz <html> para que los lectores de pantalla utilicen la voz y pronunciación correctas?", options:["charset=\"UTF-8\", concepto diferente al que se describe en esta pregunta","lang=\"es\" (o el código de idioma correspondiente)","xml=\"true\", concepto diferente al que se describe en esta pregunta","dir=\"ltr\", concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Sin el atributo lang, un lector de pantalla configurado en inglés intentará pronunciar el texto en español con fonética inglesa incomprensible.", noShuffle:false },
  { concept_id:"diw_u3_q29", unit:3, question:"¿Qué directiva de la Unión Europea obliga a la accesibilidad web en el sector público y transpone la norma EN 301 549?", options:["Directiva (UE) 2016/2102 (en España, Real Decreto 1112/2018)","Reglamento RGPD, concepto diferente al que se describe en esta pregunta","Directiva de Cookies, concepto diferente al que se describe en esta pregunta","Tratado de Lisboa, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Establece la obligatoriedad legal del cumplimiento con WCAG 2.1 nivel AA para sitios web y apps del sector público y empresas esenciales.", noShuffle:false },
  { concept_id:"diw_u3_q30", unit:3, question:"¿Qué herramienta automatizada integrada en las DevTools de Google Chrome evalúa la accesibilidad y el rendimiento de una web?", options:["Lighthouse","Network Monitor","Sources","Memory Profiler"], correct:0, explanation:"Lighthouse audita accesibilidad, buenas prácticas, SEO y métricas Core Web Vitals generando un informe porcentual detallado.", noShuffle:false },
  { concept_id:"diw_u3_q31", unit:3, question:"¿Qué extensión y motor de auditoría de accesibilidad open-source es el más reconocido para desarrolladores?", options:["axe DevTools de Deque Systems","Postman, concepto diferente al que se describe en esta pregunta","Redux DevTools, concepto diferente al que se describe en esta pregunta","React Scanner, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"axe analiza el DOM en busca de violaciones WCAG con cero falsos positivos garantizados y explicaciones técnicas de remediación.", noShuffle:false },
  { concept_id:"diw_u3_q32", unit:3, question:"¿Por qué las herramientas automáticas de accesibilidad solo pueden detectar aproximadamente entre el 30% y el 40% de los problemas reales?", options:["Porque los ordenadores son lentos, concepto diferente al que se describe en esta pregunta","Porque la accesibilidad requiere juicio humano contextual","Porque solo revisan el HTML, concepto diferente al que se describe en esta pregunta","Porque no admiten JavaScript, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La auditoría automática debe combinarse siempre con pruebas manuales de navegación por teclado y lectores de pantalla.", noShuffle:false },
  { concept_id:"diw_u3_q33", unit:3, question:"¿Qué requisito exige WCAG respecto a contenidos que parpadean o destellan en pantalla más de 3 veces por segundo?", options:["Que tengan música, concepto diferente al que se describe en esta pregunta","Deben evitarse terminantemente para prevenir desencadenar ataques epilépticos fotosensibles en usuarios vulnerables","Que sean de color azul, concepto diferente al que se describe en esta pregunta","Que duren menos de un minuto, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Criterio WCAG 2.3.1 (Three Flashes or Below Threshold): los destellos rápidos pueden provocar convulsiones neurológicas graves.", noShuffle:false },
  { concept_id:"diw_u3_q34", unit:3, question:"¿Qué etiqueta semántica de HTML5 debe utilizarse para agrupar los enlaces de navegación principales?", options:["<menu>","<nav>","<header>","<section>"], correct:1, explanation:"<nav> crea un hito de navegación (landmark) reconocido automáticamente por lectores de pantalla.", noShuffle:false },
  { concept_id:"diw_u3_q35", unit:3, question:"¿Qué etiqueta semántica de HTML5 debe envolver el contenido central y exclusivo del documento, excluyendo cabeceras y pies repetitivos?", options:["<main>","<article>","<content>","<section>"], correct:0, explanation:"Solo debe existir un elemento <main> visible por página y representa el núcleo informativo del documento.", noShuffle:false },
  { concept_id:"diw_u3_q36", unit:3, question:"¿Qué etiqueta semántica se utiliza para identificar información complementaria o secundaria (como una barra lateral de widgets)?", options:["<sidebar>","<aside>","<subnav>","<extra>"], correct:1, explanation:"<aside> define contenido relacionado tangencialmente pero separable del flujo central.", noShuffle:false },
  { concept_id:"diw_u3_q37", unit:3, question:"¿Cómo se implementa una clase utilitaria CSS para ocultar texto visualmente pero mantenerlo accesible para lectores de pantalla?", options:["display: none; o visibility: hidden;, concepto diferente al que se describe en esta pregunta","Una clase .sr-only / .visually-hidden con clip-path: inset(50%)","opacity: 0;, concepto diferente al que se describe en esta pregunta","color: transparent;, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"display: none oculta el elemento también a los lectores de pantalla; .sr-only preserva la lectura auditiva ocultando solo la visualización gráfica.", noShuffle:false },
  { concept_id:"diw_u3_q38", unit:3, question:"¿Qué atributo informa si un menú acordeón o desplegable está abierto o cerrado actualmente?", options:["aria-expanded=\"true\" / \"false\"","aria-open, concepto diferente al que se describe en esta pregunta","aria-status, concepto diferente al que se describe en esta pregunta","aria-visible, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Comunica dinámicamente al usuario con discapacidad visual si la sección subordinada se encuentra desplegada o contraída.", noShuffle:false },
  { concept_id:"diw_u3_q39", unit:3, question:"¿Qué papel juegan los subtítulos (Captions) sincronizados y las transcripciones textuales en contenidos multimedia?", options:["Mejorar la indexación de Google únicamente, concepto diferente al que se describe en esta pregunta","Permitir a personas sordas o con discapacidad auditiva acceder al contenido de audio y vídeo de forma equivalente","Aumentar el volumen del vídeo, concepto diferente al que se describe en esta pregunta","Traducir idiomas automáticamente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Criterio WCAG 1.2: todo vídeo con audio debe contar con subtítulos sincronizados cerrados (closed captions).", noShuffle:false },
  { concept_id:"diw_u3_q40", unit:3, question:"¿Qué es la 'Audiodescripción' para contenido de vídeo?", options:["Una pista de música de fondo, concepto diferente al que se describe en esta pregunta","Una pista de narración en audio adicional que describe detalles visuales clave (acciones físicas, expresiones faciales, cambios de escena) para personas ciegas durante pausas del diálogo","Un resumen en texto, concepto diferente al que se describe en esta pregunta","Un altavoz inteligente, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite a quienes no pueden ver la pantalla seguir la trama visual completa de la pieza audiovisual.", noShuffle:false },
  { concept_id:"diw_u3_q41", unit:3, question:"¿Qué es la 'Declaración de Accesibilidad' que deben publicar los sitios web sujetos a normativas públicas?", options:["Un certificado de compra, concepto diferente al que se describe en esta pregunta","Un documento público formal donde el responsable detalla el nivel de conformidad alcanzado, las excepciones, las alternativas accesibles y los canales de contacto para quejas","El código fuente de la web, concepto diferente al que se describe en esta pregunta","Un aviso de copyright, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Exigido por ley para transparentar el estado real de accesibilidad y ofrecer vías de reporte a usuarios con problemas de acceso.", noShuffle:false },
  { concept_id:"diw_u3_q42", unit:3, question:"¿Por qué se debe evitar bloquear el zoom de pellizco en dispositivos móviles mediante 'user-scalable=no' en la etiqueta meta viewport?", options:["Porque gasta más batería, concepto diferente al que se describe en esta pregunta","Porque impide a personas con baja visión ampliar el texto y las imágenes para poder leer el contenido cómodamente","Porque rompe los estilos CSS, concepto diferente al que se describe en esta pregunta","Porque Google no lo permite, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"WCAG 1.4.4 exige que el texto pueda redimensionarse hasta un 200% sin pérdida de contenido ni funcionalidad.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 4 — Animaciones, Interactividad y Multimedia Web
  // ════════════════════════════════════════════════════════════════
  { concept_id:"diw_u4_q1", unit:4, question:"¿Cuál es la diferencia entre una 'Transición' (transition) y una 'Animación' (@keyframes) en CSS?", options:["Son sinónimos, concepto diferente al que se describe en esta pregunta","Una transición requiere un cambio de estado disparador y va de un punto A a un punto B; una animación con @keyframes no requiere interacción previa, puede ejecutarse en bucle y definir múltiples pasos intermedios complejos","Las transiciones usan JavaScript, concepto diferente al que se describe en esta pregunta","Las animaciones solo mueven imágenes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"transition suaviza el cambio entre dos estados; animation permite coreografías complejas y continuas a lo largo del tiempo.", noShuffle:false },
  { concept_id:"diw_u4_q2", unit:4, question:"¿Qué cuatro valores componen la propiedad abreviada 'transition' en CSS?", options:["transition-color, transition-width, transition-left, transition-top","transition-property, transition-duration, transition-timing-function y transition-delay","name, speed, ease, loop","start, middle, end, reset"], correct:1, explanation:"Ejemplo: transition: transform 0.3s ease-in-out 0.1s; anima la propiedad transform durante 300ms con aceleración tras 100ms de espera.", noShuffle:false },
  { concept_id:"diw_u4_q3", unit:4, question:"¿Qué propiedades CSS son las únicas aceleradas por hardware en la GPU que no provocan 'Reflow' (Layout) ni 'Repaint' costosos?", options:["width y height, concepto diferente al que se describe en esta pregunta","top y left, concepto diferente al que se describe en esta pregunta","transform (translate, rotate, scale) y opacity","margin y padding, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"Animar transform y opacity se delega a la capa del Compositor de la GPU, garantizando tasas estables de 60 FPS o 120 FPS sin lag.", noShuffle:false },
  { concept_id:"diw_u4_q4", unit:4, question:"¿Qué ocurre cuando se animan propiedades de geometría como 'width', 'height', 'top' o 'margin'?", options:["El procesador las anima en la GPU, concepto diferente al que se describe en esta pregunta","Provocan el recálculo forzado de la disposición geométrica de toda la página (Layout / Reflow) en la CPU, causando tirones visuales (jank) y alto consumo de batería","La animación se congela, concepto diferente al que se describe en esta pregunta","Se cancela el CSS, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Se debe sustituir 'top/left' por 'transform: translate()' para mantener un rendimiento óptimo de renderizado.", noShuffle:false },
  { concept_id:"diw_u4_q5", unit:4, question:"¿Qué función de temporización (timing function) define una curva de aceleración personalizada basada en cuatro puntos de control en CSS?", options:["linear, concepto diferente al que se describe en esta pregunta","cubic-bezier(x1, y1, x2, y2)","ease-custom, concepto diferente al que se describe en esta pregunta","stepped(), concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"cubic-bezier permite crear efectos físicos realistas como rebotes o frenadas bruscas imposibles con ease estándar.", noShuffle:false },
  { concept_id:"diw_u4_q6", unit:4, question:"¿Qué regla de CSS define los fotogramas clave de una animación?", options:["@keyframes nombreAnimacion { 0% { ... } 100% { ... } }","@animation nombre { ... }","@frames nombre { ... }","@keyframes: name;"], correct:0, explanation:"@keyframes define los cambios de propiedades en diferentes porcentajes de la duración total de la animación.", noShuffle:false },
  { concept_id:"diw_u4_q7", unit:4, question:"¿Qué propiedad hace que una animación se repita indefinidamente sin detenerse?", options:["animation-iteration-count: infinite;","animation-loop: true;, concepto diferente al que se describe en esta pregunta","animation-repeat: forever;","repeat: infinite;, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"animation-iteration-count: infinite mantiene la animación en bucle continuo (ej: spinners de carga).", noShuffle:false },
  { concept_id:"diw_u4_q8", unit:4, question:"¿Qué valor de 'animation-fill-mode' hace que el elemento conserve los estilos del último fotograma (100%) al finalizar la animación?", options:["forwards","backwards","both","none"], correct:0, explanation:"animation-fill-mode: forwards evita que el elemento vuelva bruscamente a su estado original al terminar de animarse.", noShuffle:false },
  { concept_id:"diw_u4_q9", unit:4, question:"¿Qué propiedad de CSS avisa al navegador con antelación de qué propiedades van a cambiar para que optimice la memoria GPU antes de animar?", options:["will-change: transform, opacity;","gpu-accelerate: true;, concepto diferente al que se describe en esta pregunta","prepare-animation: on;, concepto diferente al que se describe en esta pregunta","fast-render: transform;"], correct:0, explanation:"will-change promociona el elemento a una capa de composición propia en la GPU; debe usarse con moderación para no agotar la memoria de vídeo.", noShuffle:false },
  { concept_id:"diw_u4_q10", unit:4, question:"¿Qué es el formato SVG (Scalable Vector Graphics)?", options:["Un formato de imagen de mapa de bits comprimido como JPEG","Un formato gráfico vectorial basado en XML que describe líneas","Un formato de vídeo ligero, concepto diferente al que se describe en esta pregunta","Un archivo binario de Photoshop, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"SVG es nativo de la web, manipulable con CSS y JavaScript y con un peso en bytes sumamente inferior a mapas de bits.", noShuffle:false },
  { concept_id:"diw_u4_q11", unit:4, question:"¿Cuál es la ventaja de incrustar SVG en línea (Inline SVG) directamente en el HTML frente a cargarlo mediante <img src=\"icono.svg\">?", options:["Ocupa menos espacio en disco, concepto diferente al que se describe en esta pregunta","Permite estilizar, cambiar colores (fill, stroke) y animar los caminos internos del SVG directamente con selectores de CSS y eventos de JavaScript","Carga más rápido en Internet Explorer, concepto diferente al que se describe en esta pregunta","No tiene ninguna ventaja, aunque en otros contextos puede tener cierta relevancia"], correct:1, explanation:"El SVG incrustado forma parte directa del DOM, permitiendo interacción interactiva rica e integración con temas de color.", noShuffle:false },
  { concept_id:"diw_u4_q12", unit:4, question:"¿Cuál es la diferencia principal entre el elemento <canvas> de HTML5 y un gráfico SVG?", options:["Canvas es para texto y SVG para audio, concepto diferente al que se describe en esta pregunta","<canvas> es un lienzo de mapa de bits que se dibuja píxel a píxel mediante una API imperativa de JavaScript (ideal para juegos y simulaciones de alto volumen); SVG es un árbol de objetos vectoriales retenido en el DOM","SVG es más rápido para 100.000 partículas, concepto diferente al que se describe en esta pregunta","Canvas no admite interacción, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Canvas no mantiene nodos en el DOM (modo inmediato); SVG mantiene cada elemento en el DOM accesible e interactivo.", noShuffle:false },
  { concept_id:"diw_u4_q13", unit:4, question:"¿Qué método nativo de JavaScript es el estándar para coordinar animaciones fluidas sincronizadas con la tasa de refresco del monitor?", options:["setInterval(), concepto diferente al que se describe en esta pregunta","setTimeout(), concepto diferente al que se describe en esta pregunta","window.requestAnimationFrame(callback)","performance.loop(), concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"requestAnimationFrame pausa la ejecución cuando la pestaña está en segundo plano ahorrando batería y se sincroniza a 60/120Hz sin saltos de frames.", noShuffle:false },
  { concept_id:"diw_u4_q14", unit:4, question:"¿Qué librería JavaScript moderna de código abierto es el estándar líder de la industria para animaciones complejas basadas en líneas de tiempo (timelines)?", options:["GSAP (GreenSock Animation Platform)","jQuery Animate, concepto diferente al que se describe en esta pregunta","Flash Player, concepto diferente al que se describe en esta pregunta","AnimateLite, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"GSAP ofrece un rendimiento extraordinario, compatibilidad entre navegadores y control milimétrico de secuencias.", noShuffle:false },
  { concept_id:"diw_u4_q15", unit:4, question:"¿Qué tecnología permite renderizar gráficos 2D y 3D acelerados por hardware en el navegador dentro de un <canvas> sin plugins?", options:["WebGL y WebGPU","DirectX for Web","Flash 3D","OpenGL nativo"], correct:0, explanation:"WebGL (basado en OpenGL ES) y WebGPU aprovechan la tarjeta gráfica directamente para modelado y sombreado 3D en la web.", noShuffle:false },
  { concept_id:"diw_u4_q16", unit:4, question:"¿Qué popular librería JavaScript abstrae la complejidad matemática de WebGL facilitando la creación de escenas 3D, luces y cámaras?", options:["Three.js, concepto diferente al que se describe en esta pregunta","Babylon.js, concepto diferente al que se describe en esta pregunta","Ambas a y b son librerías líderes de 3D","Chart.js, concepto diferente al que se describe en esta pregunta"], correct:2, explanation:"Three.js y Babylon.js son los dos motores de cabecera para experiencias 3D inmersivas en la web.", noShuffle:false },
  { concept_id:"diw_u4_q17", unit:4, question:"¿Qué etiqueta HTML5 se utiliza para incrustar reproductores de vídeo nativos sin necesidad de extensiones externas?", options:["<media-video>, concepto diferente al que se describe en esta pregunta","<video controls poster=\"caratula.jpg\"> <source src=\"video.mp4\" type=\"video/mp4\"> </video>","<embed type=\"video\">, concepto diferente al que se describe en esta pregunta","<movie>, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"HTML5 estandarizó la reproducción de vídeo nativo con soporte de codecs abiertos como H.264, VP9 y AV1.", noShuffle:false },
  { concept_id:"diw_u4_q18", unit:4, question:"¿Qué atributo de la etiqueta <video> silencia el audio para permitir que el navegador autorice la reproducción automática (autoplay)?", options:["mute=\"yes\"","muted","noaudio","silent"], correct:1, explanation:"Las políticas de los navegadores modernos bloquean cualquier vídeo con autoplay si no incluye el atributo 'muted' para proteger la experiencia del usuario.", noShuffle:false },
  { concept_id:"diw_u4_q19", unit:4, question:"¿Qué etiqueta HTML5 permite suministrar subtítulos y pistas de texto sincronizadas a un elemento <video> o <audio>?", options:["<caption src=\"sub.srt\">, concepto diferente al que se describe en esta pregunta","<track kind=\"subtitles\" src=\"subtitulos.vtt\" srclang=\"es\">","<text-track>, concepto diferente al que se describe en esta pregunta","<subtitles>, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"<track> lee archivos en formato estandarizado WebVTT (.vtt) sincronizados por marcas de tiempo.", noShuffle:false },
  { concept_id:"diw_u4_q20", unit:4, question:"¿Qué formato moderno de imagen para web proporciona una compresión superior a JPEG y PNG soportando transparencia y animación?", options:["WebP y AVIF","BMP, concepto diferente al que se describe en esta pregunta","TIFF, concepto diferente al que se describe en esta pregunta","GIF, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"WebP y especialmente AVIF reducen el tamaño de archivo entre un 30% y un 50% con calidad visual idéntica.", noShuffle:false },
  { concept_id:"diw_u4_q21", unit:4, question:"¿Qué etiqueta HTML permite servir diferentes formatos y resoluciones de imagen según la densidad de píxeles o el ancho del dispositivo (Responsive Images)?", options:["<responsive-img>, concepto diferente al que se describe en esta pregunta","<picture> con múltiples elementos <source> y un <img> de fallback","<img-set>, concepto diferente al que se describe en esta pregunta","<figure-adaptive>, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"<picture> permite que el navegador descargue solo el formato más ligero que soporte (ej: AVIF > WebP > JPG) y la resolución justa para la pantalla.", noShuffle:false },
  { concept_id:"diw_u4_q22", unit:4, question:"¿Qué atributo de la etiqueta <img> activa la carga perezosa nativa (Lazy Loading) para no descargar imágenes fuera de la pantalla?", options:["lazy=\"true\"","loading=\"lazy\"","defer=\"img\"","async-load"], correct:1, explanation:"loading=\"lazy\" ahorra datos y acelera el renderizado inicial al posponer la descarga hasta que la imagen se aproxima al viewport.", noShuffle:false },
  { concept_id:"diw_u4_q23", unit:4, question:"¿Qué es el formato de animación 'Lottie' creado por ingenieros de Airbnb?", options:["Un nuevo formato de vídeo comprimido, concepto diferente al que se describe en esta pregunta","Animaciones vectoriales exportadas desde Adobe After Effects como archivos JSON que se renderizan limpiamente con JavaScript a 60 FPS con un peso ínfimo","Un plugin de WordPress, concepto diferente al que se describe en esta pregunta","Un editor de imágenes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Lottie revolucionó las microanimaciones en apps y webs sustituyendo a GIFs pesados por JSONs de pocos kilobytes escalables.", noShuffle:false },
  { concept_id:"diw_u4_q24", unit:4, question:"¿Qué es la API nativa de JavaScript 'Intersection Observer'?", options:["Una API para observar las cookies, concepto diferente al que se describe en esta pregunta","Una API asíncrona de alto rendimiento que detecta cuándo un elemento entra o sale del área visible (viewport), ideal para animaciones al hacer scroll e imágenes lazy","Un radar de red, concepto diferente al que se describe en esta pregunta","Un analizador de fuentes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Sustituye a los antiguos listeners de scroll ineficientes eliminando sobrecargas en el hilo principal del navegador.", noShuffle:false },
  { concept_id:"diw_u4_q25", unit:4, question:"¿Qué es el efecto visual 'Parallax' al hacer scroll?", options:["Un fallo en la carga del CSS, concepto diferente al que se describe en esta pregunta","Una técnica visual donde los elementos de fondo se mueven a una velocidad más lenta que los elementos en primer plano, creando una ilusión óptica de profundidad 3D","Un zoom automático al pulsar, concepto diferente al que se describe en esta pregunta","Un desenfoque de movimiento, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Debe implementarse con moderación y respetando siempre 'prefers-reduced-motion' para no causar mareos.", noShuffle:false },
  { concept_id:"diw_u4_q26", unit:4, question:"¿Qué propiedad de CSS permite aplicar transformaciones en el espacio tridimensional habilitando perspectiva visual?", options:["transform: perspective(600px) rotateY(45deg); (o la propiedad perspective en el padre)","3d-view: on;, concepto diferente al que se describe en esta pregunta","depth: 600px;, concepto diferente al que se describe en esta pregunta","rotate-3d: 45;, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"perspective define la distancia entre el usuario y el plano z=0, otorgando realismo tridimensional a rotaciones.", noShuffle:false },
  { concept_id:"diw_u4_q27", unit:4, question:"¿Qué función cumple la propiedad 'transform-style: preserve-3d;' en un elemento contenedor?", options:["Mantener la imagen nítida, concepto diferente al que se describe en esta pregunta","Indica que los elementos hijos deben preservar su posición tridimensional en el espacio 3D en lugar de ser aplanados en el plano 2D del padre","Copia el estilo a otras páginas, concepto diferente al que se describe en esta pregunta","Acelera la descarga, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Indispensable para efectos de giro de tarjetas 3D (card flip) con cara frontal y trasera.", noShuffle:false },
  { concept_id:"diw_u4_q28", unit:4, question:"¿Qué propiedad de CSS oculta la cara posterior de un elemento cuando este rota 180 grados mostrando su reverso?", options:["backface-visibility: hidden;","hide-back: true;, concepto diferente al que se describe en esta pregunta","reverse-face: none;, concepto diferente al que se describe en esta pregunta","face-display: front;"], correct:0, explanation:"Permite que al voltear una tarjeta se muestre la cara opuesta colocada detrás sin interferencias visuales.", noShuffle:false },
  { concept_id:"diw_u4_q29", unit:4, question:"¿Qué propiedad CSS permite recortar un elemento con formas geométricas arbitrarias (polígonos, círculos, elipses)?", options:["clip-path (ej: clip-path: polygon(0 0, 100% 0, 100% 80%","mask-crop, concepto diferente al que se describe en esta pregunta","shape-cut, concepto diferente al que se describe en esta pregunta","border-clip, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"clip-path define regiones visibles vectoriales y puede animarse con transiciones si los polígonos tienen el mismo número de vértices.", noShuffle:false },
  { concept_id:"diw_u4_q30", unit:4, question:"¿Qué propiedad de CSS permite mezclar visualmente los colores de capas superpuestas (como en Photoshop: multiply, screen, overlay)?", options:["mix-blend-mode (y background-blend-mode)","color-mix, concepto diferente al que se describe en esta pregunta","blend-color, concepto diferente al que se describe en esta pregunta","filter-blend, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"mix-blend-mode fusiona los píxeles del elemento con el contenido situado detrás en el DOM.", noShuffle:false },
  { concept_id:"diw_u4_q31", unit:4, question:"¿Qué evento de JavaScript se dispara cuando una animación de CSS (@keyframes) concluye su ciclo completo?", options:["animationend","animationfinish","animationstop","keyframeover"], correct:0, explanation:"element.addEventListener('animationend', callback) permite sincronizar acciones o eliminar elementos tras desvanecerse.", noShuffle:false },
  { concept_id:"diw_u4_q32", unit:4, question:"¿Qué evento de JavaScript se dispara cuando una transición de CSS (transition) termina de ejecutarse?", options:["transitionend","transitionfinish","transitioncomplete","transover"], correct:0, explanation:"Permite saber exactamente cuándo concluyó la transición para ejecutar la siguiente fase lógica del script.", noShuffle:false },
  { concept_id:"diw_u4_q33", unit:4, question:"¿Qué es el 'Layout Shift' o parpadeo acumulado (CLS - Cumulative Layout Shift)?", options:["El cambio de idioma de la web, concepto que se aplica en un contexto distinto","El movimiento inesperado de elementos de la página mientras el usuario la está leyendo, provocado habitualmente por imágenes o anuncios insertados sin dimensiones preestablecidas","El parpadeo del cursor, concepto diferente al que se describe en esta pregunta","El cambio de tema oscuro a claro, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Es una de las métricas vitales (Core Web Vitals) penalizadas por Google en el posicionamiento y la experiencia de usuario.", noShuffle:false },
  { concept_id:"diw_u4_q34", unit:4, question:"¿Qué formato de fuentes web es el estándar moderno más comprimido y optimizado para su descarga en la web?", options:["TTF (TrueType), concepto diferente al que se describe en esta pregunta","WOFF2 (Web Open Font Format 2)","EOT, concepto diferente al que se describe en esta pregunta","SVG Font, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"WOFF2 utiliza el algoritmo de compresión Brotli, reduciendo el peso de la tipografía cerca de un 30% respecto a WOFF y TTF.", noShuffle:false },
  { concept_id:"diw_u4_q35", unit:4, question:"¿Qué directiva de la regla @font-face controla cómo se muestra el texto mientras la fuente externa se descarga por internet?", options:["font-display: swap; (o block, fallback, optional)","font-loading: async;, concepto diferente al que se describe en esta pregunta","text-render: fast;, concepto diferente al que se describe en esta pregunta","font-cache: on;, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"font-display: swap muestra inmediatamente una fuente del sistema de respaldo y la 'intercambia' por la fuente personalizada al descargarse, evitando texto invisible (FOIT).", noShuffle:false },
  { concept_id:"diw_u4_q36", unit:4, question:"¿Qué es una 'Variable Font' (Fuente Variable)?", options:["Una fuente que cambia de nombre, concepto diferente al que se describe en esta pregunta","Un archivo de tipografía único que contiene múltiples pesos","Una tipografía gratuita, concepto diferente al que se describe en esta pregunta","Un conversor de fuentes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ahorra decenas de peticiones HTTP al no tener que descargar un archivo .woff2 separado para cada peso (regular, bold, light).", noShuffle:false },
  { concept_id:"diw_u4_q37", unit:4, question:"¿Qué propiedad de CSS aplica filtros gráficos instantáneos como desenfoque, brillo, contraste o escala de grises?", options:["filter (ej: filter: blur(5px) grayscale(100%);)","image-filter, concepto diferente al que se describe en esta pregunta","fx, concepto diferente al que se describe en esta pregunta","render-effect, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"filter aplica efectos de procesamiento de imagen en tiempo real mediante la GPU.", noShuffle:false },
  { concept_id:"diw_u4_q38", unit:4, question:"¿Qué es el 'Web Audio API' de JavaScript frente a la etiqueta básica <audio>?", options:["Un reproductor de radio por internet, concepto diferente al que se describe en esta pregunta","Una API avanzada de procesamiento y síntesis de audio de bajo nivel que permite manipular fuentes sonoras, añadir filtros, espacialización 3D y análisis de frecuencias en tiempo real","Un plugin de Spotify, concepto diferente al que se describe en esta pregunta","Un conversor de MP3 a WAV, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite generar música procedural interactiva, efectos de sonido para videojuegos web y visualizadores de audio en canvas.", noShuffle:false },
  { concept_id:"diw_u4_q39", unit:4, question:"¿Qué protocolo de compresión de vídeo moderno desarrollado por la Alliance for Open Media (AOMedia) ofrece compresión libre de royalties superior a HEVC y VP9?", options:["AV1","Flash Video","MPEG-2","QuickTime"], correct:0, explanation:"AV1 es el códec de vídeo abierto de última generación respaldado por Google, Mozilla, Apple y Netflix para la web moderna.", noShuffle:false },
  { concept_id:"diw_u4_q40", unit:4, question:"¿Cómo se puede precargar un recurso multimedia crítico (ej: la fuente principal o la imagen hero) con la máxima prioridad en el <head>?", options:["<link rel=\"preload\" href=\"fuente.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>","<script preload src=\"...\">, concepto diferente al que se describe en esta pregunta","<meta preload=\"...\">, concepto diferente al que se describe en esta pregunta","<img eager-load src=\"...\">, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"rel=\"preload\" indica al navegador que comience a descargar el recurso de inmediato antes de que el motor de render descubra su referencia en el CSS.", noShuffle:false },
  { concept_id:"diw_u4_q41", unit:4, question:"¿Qué es el 'Scroll-Driven Animations' en CSS nativo moderno?", options:["Animaciones que se activan solo con ratón","Animaciones cuyo progreso está vinculado directamente a la posición de desplazamiento de un contenedor de scroll usando propiedades como 'animation-timeline: scroll()' sin una sola línea de JS","Un script de jQuery","Un error de desbordamiento"], correct:0, explanation:"Permite barras de progreso de lectura y efectos de revelado al scroll ejecutados en el hilo del compositor con 0 sobrecarga de JS.", noShuffle:false },
  { concept_id:"diw_u4_q42", unit:4, question:"¿Qué propiedad CSS asegura que los controles de reproducción de un elemento <video> o <audio> se muestren al usuario?", options:["controls","autoplay","show-buttons","player"], correct:0, explanation:"El atributo booleano 'controls' añade la barra nativa del navegador con play/pause, volumen y pantalla completa.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 5 — Frameworks CSS, Preprocesadores y Sistemas de Diseño
  // ════════════════════════════════════════════════════════════════
  { concept_id:"diw_u5_q1", unit:5, question:"¿Qué es un preprocesador CSS como Sass (Syntactically Awesome Style Sheets)?", options:["Un navegador web, concepto diferente al que se describe en esta pregunta","Un programa que extiende la sintaxis estándar de CSS permitiendo variables, anidamiento, mixins y funciones, compilándolo finalmente a CSS plano estándar legible por navegadores","Un editor de código, concepto diferente al que se describe en esta pregunta","Un validador de accesibilidad, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Sass añade potencia y modularidad al desarrollo de hojas de estilo antes de que muchas características llegaran de forma nativa a CSS.", noShuffle:false },
  { concept_id:"diw_u5_q2", unit:5, question:"¿Cuáles son las dos sintaxis disponibles en Sass?", options:["HTML y CSS","SCSS (Sassy CSS, con llaves {} y punto y coma ;, compatible con CSS estándar) y la sintaxis indentada original Sass (basada en sangría sin llaves)","TypeScript y JavaScript","BEM y Atomic"], correct:1, explanation:"SCSS (.scss) es la sintaxis más adoptada universalmente por permitir copiar y pegar CSS válido directamente.", noShuffle:false },
  { concept_id:"diw_u5_q3", unit:5, question:"¿Qué es un 'Mixin' en Sass y cómo se declara e incluye?", options:["Una variable numérica, concepto diferente al que se describe en esta pregunta","Un bloque reutilizable de código CSS que puede aceptar parámetros","Una clase de Bootstrap, concepto diferente al que se describe en esta pregunta","Un plugin de compilación, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los mixins evitan duplicar fragmentos repetitivos de estilos y permiten parametrizar valores dinámicos.", noShuffle:false },
  { concept_id:"diw_u5_q4", unit:5, question:"¿Qué función cumple la directiva '@extend' en Sass?", options:["Hacer la pantalla más ancha es una accion que no define correctamente este concepto","Permite que un selector herede todos los estilos de otro selector o clase de plantilla (%placeholder) compartiendo reglas CSS compiladas para no duplicar código","Cargar fuentes de internet, concepto diferente al que se describe en esta pregunta","Ampliar el límite de memoria, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"@extend ayuda a aplicar el principio DRY (Don't Repeat Yourself) agrupando selectores en la salida compilada.", noShuffle:false },
  { concept_id:"diw_u5_q5", unit:5, question:"¿Qué representa el carácter especial '&' dentro de un bloque anidado en Sass?", options:["El operador lógico AND, concepto diferente al que se describe en esta pregunta","Una referencia directa al selector padre exterior en el que se encuentra anidado","Una variable especial, concepto diferente al que se describe en esta pregunta","Un comentario, concepto que no se corresponde con la definicion correcta"], correct:1, explanation:"Permite componer selectores BEM y pseudoclases de forma sumamente limpia y legible.", noShuffle:false },
  { concept_id:"diw_u5_q6", unit:5, question:"¿Por qué se desaconseja anidar selectores a más de 3 niveles de profundidad en Sass (el 'problema del anidamiento excesivo')?", options:["Porque el compilador se rompe, concepto diferente al que se describe en esta pregunta","Porque genera selectores compilados con una especificidad monstruosa e inmanejable que infla el tamaño del archivo final y hace imposible sobreescribir estilos","Porque no funciona en Chrome, concepto diferente al que se describe en esta pregunta","Porque prohíbe el uso de clases, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La regla de oro es 'no anidar más de 3 niveles de profundidad' para mantener especificidades bajas y arquitectura limpia.", noShuffle:false },
  { concept_id:"diw_u5_q7", unit:5, question:"¿Qué directivas modernas reemplazaron a la antigua y problemática directiva '@import' en Sass?", options:["@use y @forward","@require y @include","@load y @link","@import2 y @fetch"], correct:0, explanation:"@use aísla las variables y mixins en namespaces propios (evitando colisiones globales) y solo compila el archivo una única vez.", noShuffle:false },
  { concept_id:"diw_u5_q8", unit:5, question:"¿Qué es la metodología BEM (Bloque, Elemento, Modificador) para nombrar clases en CSS?", options:["Un algoritmo de compresión, concepto diferente al que se describe en esta pregunta","Una convención de nomenclatura estandarizada que estructura los nombres de clases como bloque__elemento--modificador para evitar colisiones de especificidad","Una librería de JavaScript, concepto diferente al que se describe en esta pregunta","Un framework de backend, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"BEM garantiza que todas las clases tengan la misma especificidad baja (una sola clase) y clarifica la relación semántica de los componentes.", noShuffle:false },
  { concept_id:"diw_u5_q9", unit:5, question:"En la metodología BEM, ¿qué representa el 'Bloque'?", options:["Un error de renderizado, concepto diferente al que se describe en esta pregunta","Una entidad autónoma e independiente con significado por sí misma que puede reutilizarse en cualquier parte de la interfaz","Un párrafo de texto, concepto diferente al que se describe en esta pregunta","Un elemento hijo obligatorio, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El Bloque es el contenedor raíz del componente que encapsula su comportamiento y apariencia.", noShuffle:false },
  { concept_id:"diw_u5_q10", unit:5, question:"En BEM, ¿cómo se delimita sintácticamente un 'Elemento' respecto a su Bloque padre?", options:["Con un punto, concepto diferente al que se describe en esta pregunta","Con dos guiones bajos: bloque__elemento (ej: .card__titulo","Con un guion simple, concepto diferente al que se describe en esta pregunta","Con dos almohadillas, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El doble guion bajo (__elemento) denota que ese elemento solo tiene sentido y existencia dentro de su Bloque contenedor.", noShuffle:false },
  { concept_id:"diw_u5_q11", unit:5, question:"En BEM, ¿cómo se delimita un 'Modificador' que altera el aspecto o estado de un bloque o elemento?", options:["Con dos guiones medios: elemento--modificador (ej: .btn--primario","Con dos barras //, concepto diferente al que se describe en esta pregunta","Con un signo más +, concepto diferente al que se describe en esta pregunta","Con comillas, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"El doble guion medio (--modificador) expresa una variante visual o estado alternativo del componente.", noShuffle:false },
  { concept_id:"diw_u5_q12", unit:5, question:"¿Cuál es la filosofía de diseño fundamental de Tailwind CSS frente a frameworks como Bootstrap?", options:["Tailwind solo sirve para animaciones, concepto diferente al que se describe en esta pregunta","Tailwind es un framework 'Utility-First' que proporciona clases atómicas de bajo nivel para construir diseños personalizados sin salir del HTML, sin imponer componentes prediseñados","Tailwind no usa CSS, concepto diferente al que se describe en esta pregunta","Bootstrap es más rápido siempre, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Tailwind no impone botones o tarjetas cerradas; da bloques elementales universales para crear cualquier diseño sin pelear contra estilos impuestos.", noShuffle:false },
  { concept_id:"diw_u5_q13", unit:5, question:"¿Cómo optimiza Tailwind CSS el tamaño del archivo final de estilos en entornos de producción mediante su motor JIT (Just-in-Time)?", options:["Comprime el archivo en un zip, concepto diferente al que se describe en esta pregunta","Escanea todo el código HTML/JS en busca de las clases utilitarias efectivamente empleadas y genera un archivo CSS minificado únicamente con las reglas utilizadas, purgando el resto","Borra las clases que no le gustan, concepto diferente al que se describe en esta pregunta","Descarga los estilos de internet, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El compilador elimina todo el CSS innecesario logrando cargas instantáneas.", noShuffle:false },
  { concept_id:"diw_u5_q14", unit:5, question:"¿En qué archivo de configuración se personaliza la paleta de colores, tipografías, puntos de ruptura (breakpoints) y plugins de un proyecto Tailwind?", options:["tailwind.config.js","tailwind.json","package.json","styles.config"], correct:0, explanation:"tailwind.config.js es el corazón del tema donde se extiende o sobreescribe el diseño del sistema.", noShuffle:false },
  { concept_id:"diw_u5_q15", unit:5, question:"¿Qué directiva de Tailwind CSS permite agrupar múltiples clases utilitarias en una sola clase personalizada dentro de un archivo CSS?", options:["@apply (ej: .btn-custom { @apply px-4 py-2 bg-blue-500 rounded; })","@include","@extend","@mixin"], correct:0, explanation:"@apply extrae utilidades repetitivas a clases compuestas cuando la duplicación en plantillas es excesiva.", noShuffle:false },
  { concept_id:"diw_u5_q16", unit:5, question:"¿Qué sistema de rejilla (Grid System) utiliza tradicionalmente el framework Bootstrap?", options:["Un sistema flexible basado en 12 columnas (row y col-1 a col-12) apoyado en Flexbox","Un sistema de 8 columnas, que aunque es una herramienta util, no corresponde a esta definicion","Un sistema de 10 columnas sin márgenes, que aunque es una herramienta util, no corresponde a esta definicion","Tablas HTML nativas, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"La división en 12 columnas permite fraccionar en mitades (6+6), tercios (4+4+4), cuartos (3+3+3+3) o sextos de forma intuitiva.", noShuffle:false },
  { concept_id:"diw_u5_q17", unit:5, question:"¿Qué prefijo de clase responsive en Bootstrap aplica estilos a partir de pantallas de tamaño mediano (tablets, >= 768px)?", options:["col-sm-, concepto diferente al que se describe en esta pregunta","col-md- (ej: col-md-6)","col-lg-, concepto diferente al que se describe en esta pregunta","col-xl-, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"sm (>=576px), md (>=768px), lg (>=992px), xl (>=1200px), xxl (>=1400px).", noShuffle:false },
  { concept_id:"diw_u5_q18", unit:5, question:"¿Qué es PostCSS?", options:["Un competidor de WordPress, concepto diferente al que se describe en esta pregunta","Una herramienta que transforma estilos CSS mediante plugins de JavaScript","Un servicio de correos, concepto diferente al que se describe en esta pregunta","Una base de datos de estilos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"PostCSS parsea CSS en un AST y permite manipularlo; es el motor subyacente sobre el que se ejecuta Tailwind CSS y Autoprefixer.", noShuffle:false },
  { concept_id:"diw_u5_q19", unit:5, question:"¿Qué hace el plugin 'Autoprefixer' en un pipeline de frontend?", options:["Formatea el código con espacios, concepto diferente al que se describe en esta pregunta","Añade automáticamente los prefijos propietarios de los navegadores (-webkit-, -moz-, -ms-) a las reglas CSS basándose en los datos de compatibilidad de CanIUse","Reescribe las imágenes, concepto diferente al que se describe en esta pregunta","Borra selectores antiguos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite al programador escribir CSS estándar limpio sin memorizar qué propiedades requieren prefijos para navegadores más antiguos.", noShuffle:false },
  { concept_id:"diw_u5_q20", unit:5, question:"¿Qué es un 'Design System' (Sistema de Diseño)?", options:["Un programa como Photoshop, que aunque es una herramienta util, no corresponde a esta definicion","Un conjunto único de principios, guías de estilo, tokens de diseño y componentes de código reutilizables gobernados por estándares claros que aseguran la consistencia visual y funcional en toda una organización","Un conjunto de wireframes, concepto diferente al que se describe en esta pregunta","Una plantilla de PowerPoint, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Sistemas como Material Design (Google) o Carbon (IBM) alinean el trabajo de diseñadores y programadores a gran escala.", noShuffle:false },
  { concept_id:"diw_u5_q21", unit:5, question:"¿Qué son los 'Design Tokens' (Tokens de Diseño)?", options:["Monedas criptográficas de diseño, concepto diferente al que se describe en esta pregunta","Los valores visuales atómicos más elementales de un sistema de diseño almacenados como datos agnósticos (JSON/YAML) que definen colores, tipografías, espaciados y sombras para exportarse a CSS, iOS y Android","Iconos vectoriales, concepto diferente al que se describe en esta pregunta","Licencias de tipografías, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permiten que un cambio de color central en el JSON se propague automáticamente a las aplicaciones web, móviles y documentación.", noShuffle:false },
  { concept_id:"diw_u5_q22", unit:5, question:"¿Qué es la metodología 'Atomic Design' formulada por Brad Frost?", options:["Un reactor nuclear en la web, concepto diferente al que se describe en esta pregunta","Una metodología para crear sistemas de diseño basada en la jerarquía química dividida en cinco etapas: Átomos, Moléculas, Organismos, Plantillas y Páginas","Un tipo de física de partículas, concepto diferente al que se describe en esta pregunta","Un framework de JavaScript, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Estructura las interfaces de lo más elemental (un botón) a combinaciones complejas (una barra de búsqueda, una cabecera y una página completa).", noShuffle:false },
  { concept_id:"diw_u5_q23", unit:5, question:"En Atomic Design, ¿qué es una 'Molécula'?", options:["Un archivo CSS completo, concepto diferente al que se describe en esta pregunta","La unión funcional de dos o más átomos que actúan como una unidad operativa simple","Un componente de 1000 líneas, concepto diferente al que se describe en esta pregunta","Una base de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las moléculas tienen un propósito único y tangible combinando átomos elementales.", noShuffle:false },
  { concept_id:"diw_u5_q24", unit:5, question:"En Atomic Design, ¿qué es un 'Organismo'?", options:["El usuario que visita la web, concepto diferente al que se describe en esta pregunta","Un componente complejo formado por la combinación de moléculas","El servidor web, concepto diferente al que se describe en esta pregunta","Un archivo HTML, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los organismos representan bloques completos y coherentes de la interfaz.", noShuffle:false },
  { concept_id:"diw_u5_q25", unit:5, question:"¿Qué herramienta de código abierto es el estándar de la industria para desarrollar, aislar y documentar componentes de UI en un entorno interactivo fuera de la aplicación principal?", options:["Storybook","Figma únicamente","Postman","Jenkins"], correct:0, explanation:"Storybook permite probar todos los estados y variantes de los componentes de forma aislada facilitando el testeo y el mantenimiento del Design System.", noShuffle:false },
  { concept_id:"diw_u5_q26", unit:5, question:"¿Qué es 'CSS Reset' frente a 'Normalize.css'?", options:["No hay diferencia, aunque algunos enfoques establecen matices al respecto","CSS Reset elimina agresivamente todos los márgenes, paddings y estilos por defecto del navegador fijándolos a cero; Normalize.css preserva valores predeterminados útiles y corrige inconsistencias y bugs entre navegadores respetando la semántica","Reset es más moderno, concepto diferente al que se describe en esta pregunta","Normalize es un virus, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Normalize.css ofrece una base más limpia y predecible sin tener que redeclarar estilos básicos como negritas o listas.", noShuffle:false },
  { concept_id:"diw_u5_q27", unit:5, question:"¿Qué es una 'Guía de Estilo' (Style Guide) en desarrollo de interfaces?", options:["Un manual de instrucciones del servidor, concepto diferente al que se describe en esta pregunta","Un documento normativo que recoge las directrices visuales de la marca: logotipos, paleta cromática, escala tipográfica, iconografía, patrones de espaciado y tono de voz","Una lista de contraseñas, concepto diferente al que se describe en esta pregunta","Un tutorial de Git, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Asegura que cualquier nuevo diseño o pantalla respete rigurosamente la identidad corporativa.", noShuffle:false },
  { concept_id:"diw_u5_q28", unit:5, question:"¿Qué es 'CSS Modules' en arquitecturas de aplicaciones modernas (React, Vue)?", options:["Módulos de Apache para CSS, concepto diferente al que se describe en esta pregunta","Una técnica de compilación donde todas las clases de un archivo .module.css se transforman en nombres únicos con hash en tiempo de compilación para garantizar ámbito local estricto sin colisiones globales","Un plugin de CSS, concepto diferente al que se describe en esta pregunta","Un framework como Bootstrap, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Resuelve definitivamente el problema histórico de las colisiones de nombres globales en aplicaciones a gran escala.", noShuffle:false },
  { concept_id:"diw_u5_q29", unit:5, question:"¿Qué enfoque representan librerías como styled-components o Emotion en el ecosistema de componentes?", options:["CSS-in-JS: escribir estilos CSS reales encapsulados dentro de los propios archivos de componentes JavaScript aprovechando variables y lógica del lenguaje","HTML puro, concepto diferente al que se describe en esta pregunta","Sass sin compilar, concepto diferente al que se describe en esta pregunta","Bootstrap clásico, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"CSS-in-JS vincula fuertemente los estilos al ciclo de vida y props del componente de frontend.", noShuffle:false },
  { concept_id:"diw_u5_q30", unit:5, question:"¿Qué es la arquitectura 'ITCSS' (Inverted Triangle CSS) para organizar hojas de estilo?", options:["Un virus con forma de triángulo, concepto diferente al que se describe en esta pregunta","Una arquitectura organizativa que ordena el código CSS en capas de menor a mayor especificidad y de lo global a lo explícito: Settings > Tools > Generic > Elements > Objects > Components > Utilities","Un framework de Google, concepto diferente al que se describe en esta pregunta","Una regla de Grid, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Previene las guerras de especificidad estructurando el proyecto de forma escalable y sin parches.", noShuffle:false },
  { concept_id:"diw_u5_q31", unit:5, question:"¿Qué son los 'Icon Fonts' frente a los 'SVG Sprites' en iconografía web?", options:["Son idénticos, concepto diferente al que se describe en esta pregunta","Icon Fonts empaquetan iconos vectoriales como glifos en una tipografía personalizada; SVG Sprites agrupan iconos SVG en un único archivo XML referenciado con <use href=\"#icono\">","Icon Fonts son mejores en accesibilidad, concepto diferente al que se describe en esta pregunta","SVG Sprites pesan más siempre, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los SVG Sprites son la técnica recomendada moderna por ser más nítidos en pantallas de alta densidad y mucho más accesibles para lectores de pantalla.", noShuffle:false },
  { concept_id:"diw_u5_q32", unit:5, question:"¿Qué directiva de CSS permite agrupar reglas en capas de cascada declarativas con prioridad explícita independiente de la especificidad?", options:["@layer (ej: @layer base, components, utilities;)","@priority, concepto diferente al que se describe en esta pregunta","@cascade, concepto diferente al que se describe en esta pregunta","@stack, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"@layer (CSS Cascade Layers) estandariza el control de qué capas de estilos (ej: frameworks vs overrides) ganan en la cascada.", noShuffle:false },
  { concept_id:"diw_u5_q33", unit:5, question:"¿Cómo se compila un archivo Sass 'estilos.scss' a 'estilos.css' desde la terminal usando la herramienta oficial Dart Sass?", options:["sass estilos.scss estilos.css","compile-sass estilos","npm run css","sass --make estilos.scss"], correct:0, explanation:"sass origen.scss destino.css genera el archivo CSS plano. Con el flag --watch recompila automáticamente al guardar cambios.", noShuffle:false },
  { concept_id:"diw_u5_q34", unit:5, question:"¿Qué es un 'Source Map' (.css.map) en herramientas de preprocesado y empaquetado de CSS?", options:["Un mapa geográfico, concepto diferente al que se describe en esta pregunta","Un archivo que mapea las líneas del CSS compilado y minificado con las líneas y archivos fuente originales de Sass/SCSS en las herramientas de desarrollo del navegador para facilitar la depuración","Un diagrama de clases, concepto diferente al que se describe en esta pregunta","Una lista de URLs, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite inspeccionar un elemento en Chrome y ver directamente el archivo y línea .scss donde se declaró la regla.", noShuffle:false },
  { concept_id:"diw_u5_q35", unit:5, question:"¿Qué herramienta CLI audita y aplica reglas estrictas de formato y calidad de código en archivos CSS y SCSS?", options:["Stylelint","ESLint exclusivo","Prettier únicamente","CSSValidator"], correct:0, explanation:"Stylelint detecta errores de sintaxis, reglas no conformes, colores no autorizados y convenciones de nombres en equipos.", noShuffle:false },
  { concept_id:"diw_u5_q36", unit:5, question:"¿Qué es una 'Escala Tipográfica Modular' (Modular Typography Scale)?", options:["Una regla de medir fuentes, concepto diferente al que se describe en esta pregunta","Una serie coherente de tamaños de letra calculados a partir de un tamaño base multiplicado por una proporción matemática armónica fija","Un tipo de fuente monospaced, concepto diferente al que se describe en esta pregunta","Un listado aleatorio de tamaños, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Garantiza una jerarquía visual armónica y predecible entre párrafos, subtítulos y encabezados en toda la interfaz.", noShuffle:false },
  { concept_id:"diw_u5_q37", unit:5, question:"¿Qué paleta de colores semántica es estándar en la mayoría de Design Systems y frameworks de UI?", options:["Rojo, verde y azul únicamente, concepto diferente al que se describe en esta pregunta","Colores primarios, secundarios, neutros (grises de fondo y texto) y colores semánticos de estado (Success/Éxito, Warning/Aviso, Danger/Peligro, Info/Informativo)","Colores pastel únicamente, concepto diferente al que se describe en esta pregunta","Blanco y negro, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Los colores de estado asocian convenciones universales e inmediatas a las alertas y mensajes del sistema.", noShuffle:false },
  { concept_id:"diw_u5_q38", unit:5, question:"¿Qué ventaja tiene utilizar unidades relativas a la raíz (rem) en lugar de píxeles fijos (px) en el sistema de diseño?", options:["Las fuentes se descargan más rápido, concepto diferente al que se describe en esta pregunta","Permite que toda la interfaz escale proporcionalmente de forma automática si el usuario modifica el tamaño de fuente predeterminado en las opciones de accesibilidad de su navegador","Los píxeles están obsoletos, concepto diferente al que se describe en esta pregunta","rem ocupa menos bytes, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Respetar las preferencias de accesibilidad del usuario es un pilar ético y técnico de la maquetación moderna.", noShuffle:false },
  { concept_id:"diw_u5_q39", unit:5, question:"¿Qué es 'Chakra UI' o 'shadcn/ui' en el desarrollo de componentes web modernos?", options:["Sistemas operativos, concepto diferente al que se describe en esta pregunta","Colecciones de componentes accesibles y personalizables construidos sobre primitivas accesibles (como Radix UI) diseñados para integrarse directamente en la base de código del proyecto","Editores de vídeo, concepto diferente al que se describe en esta pregunta","Bases de datos NoSQL, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"shadcn/ui se popularizó por no ser una dependencia empaquetada cerrada en node_modules, sino código que se copia directamente en el proyecto con control total.", noShuffle:false },
  { concept_id:"diw_u5_q40", unit:5, question:"¿Qué componente de Bootstrap se utiliza para mostrar alertas emergentes flotantes no intrusivas en una esquina de la pantalla?", options:["Modal","Toasts","Tooltips","Badges"], correct:1, explanation:"Los Toasts son notificaciones push ligeras similares a las de los sistemas operativos móviles.", noShuffle:false },
  { concept_id:"diw_u5_q41", unit:5, question:"¿Cómo se implementa un sistema de 'Dark Mode' limpio mediante variables CSS en una web?", options:["Haciendo dos webs independientes, concepto diferente al que se describe en esta pregunta","Definiendo variables de colores semánticos (--bg, --text) en :root y sobreescribiendo sus valores dentro de una clase .dark o dentro de @media (prefers-color-scheme: dark)","Invertir todos los colores con un filtro invert(100%), concepto diferente al que se describe en esta pregunta","Apagar el brillo con JavaScript, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Invertir con filtros rompe imágenes y fotos; cambiar los tokens de color garantiza contraste, legibilidad y armonía visual perfecta.", noShuffle:false },
  { concept_id:"diw_u5_q42", unit:5, question:"¿Qué beneficio aporta la colaboración en un Sistema de Diseño entre los equipos de Diseño (Figma) y Desarrollo (CSS)?", options:["Cobrar el doble es una accion que no define correctamente este concepto","Acelera los tiempos de entrega, reduce la duplicación de código","Permite prescindir de los programadores, concepto diferente al que se describe en esta pregunta","Evita usar Git, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Crea un lenguaje común compartido (Single Source of Truth) que sincroniza especificaciones y componentes reales.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 6 — Prototipado, Validación y Testing de Interfaces
  // ════════════════════════════════════════════════════════════════
  { concept_id:"diw_u6_q1", unit:6, question:"¿Qué herramienta basada en la nube se ha consolidado como el estándar líder de la industria para diseño colaborativo de interfaces y prototipado interactivo?", options:["Figma","Paint","Microsoft Word","Sublime Text"], correct:0, explanation:"Figma permite a múltiples diseñadores y desarrolladores trabajar en tiempo real en el mismo lienzo desde el navegador.", noShuffle:false },
  { concept_id:"diw_u6_q2", unit:6, question:"¿Qué función de Figma permite crear componentes flexibles y adaptables que ajustan automáticamente su espaciado y tamaño según el contenido, análogo a Flexbox?", options:["Auto Layout","Smart Animate","Variants","Frame Resizing"], correct:0, explanation:"Auto Layout reproduce exactamente el comportamiento de Flexbox (dirección, padding, gap, alignment) dentro de Figma.", noShuffle:false },
  { concept_id:"diw_u6_q3", unit:6, question:"¿Qué función de Figma permite agrupar diferentes estados visuales (ej: Default, Hover, Active, Disabled) de un mismo componente en un único bloque organizado?", options:["Component Variants (Variantes de Componentes)","Auto Animate, concepto diferente al que se describe en esta pregunta","Plugins, concepto diferente al que se describe en esta pregunta","Styles, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Las variantes permiten a los diseñadores y desarrolladores seleccionar estados mediante propiedades conmutables limpias.", noShuffle:false },
  { concept_id:"diw_u6_q4", unit:6, question:"¿Qué es el modo 'Dev Mode' en Figma?", options:["Un compilador de C++, concepto diferente al que se describe en esta pregunta","Un espacio de trabajo especializado para programadores que permite inspeccionar medidas exactas, exportar tokens, ver propiedades CSS y copiar fragmentos de código listos para producción","Un modo para jugar a videojuegos, concepto diferente al que se describe en esta pregunta","Un generador automático de bases de datos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Facilita el 'Design Handoff' reduciendo la fricción en la traducción de diseños a maquetación real.", noShuffle:false },
  { concept_id:"diw_u6_q5", unit:6, question:"¿Qué es el 'A/B Testing' (Pruebas A/B) en optimización de interfaces?", options:["Un examen tipo test con dos opciones, concepto diferente al que se describe en esta pregunta","Un experimento controlado donde dos variantes de una interfaz (versión A original y versión B con una modificación) se muestran aleatoriamente a distintos grupos de usuarios para medir cuál convierte mejor","Probar en dos ordenadores distintos, concepto diferente al que se describe en esta pregunta","Hacer pruebas por la mañana y por la tarde es una accion que no define correctamente este concepto"], correct:1, explanation:"Permite tomar decisiones de diseño basadas en datos empíricos de comportamiento real y no en suposiciones.", noShuffle:false },
  { concept_id:"diw_u6_q6", unit:6, question:"¿Qué métrica evalúa el porcentaje de usuarios que completan con éxito una acción deseada (comprar, suscribirse, registrarse) en una interfaz?", options:["Bounce Rate, concepto diferente al que se describe en esta pregunta","Conversion Rate (Tasa de Conversión)","Churn Rate, concepto diferente al que se describe en esta pregunta","Click Rate, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"La tasa de conversión es el indicador clave de rendimiento (KPI) principal para valorar la eficacia de una interfaz digital.", noShuffle:false },
  { concept_id:"diw_u6_q7", unit:6, question:"¿Qué es un 'Test de Usabilidad con Usuarios' (Moderado o No Moderado)?", options:["Un test automático de velocidad, concepto diferente al que se describe en esta pregunta","Una sesión donde se observa y graba a usuarios representativos reales mientras intentan completar una serie de tareas típicas en la interfaz, identificando atascos y confusiones","Un examen de informática para los usuarios, concepto diferente al que se describe en esta pregunta","Una encuesta anónima de satisfacción, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite descubrir problemas de usabilidad críticos que los diseñadores no podían anticipar por estar familiarizados con el producto.", noShuffle:false },
  { concept_id:"diw_u6_q8", unit:6, question:"¿Qué método de evaluación UX consiste en pedir al usuario que verbalice sus pensamientos, dudas e impresiones en voz alta mientras interactúa con la interfaz?", options:["Think-Aloud Protocol (Protocolo de Pensamiento en Voz Alta)","Card Sorting, concepto diferente al que se describe en esta pregunta","Entrevista ciega, concepto diferente al que se describe en esta pregunta","Evaluación silenciosa, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"El Think-Aloud revela el modelo mental del usuario y las causas exactas de su vacilación o error en tiempo real.", noShuffle:false },
  { concept_id:"diw_u6_q9", unit:6, question:"¿Cuántos usuarios son suficientes para descubrir aproximadamente el 80%-85% de los problemas de usabilidad principales de una interfaz según Jakob Nielsen?", options:["1 usuario","5 usuarios","100 usuarios","1000 usuarios"], correct:1, explanation:"Nielsen demostró que las curvas de descubrimiento de fallos tienen rendimientos decrecientes: 5 usuarios detectan la gran mayoría de problemas graves.", noShuffle:false },
  { concept_id:"diw_u6_q10", unit:6, question:"¿Qué es un 'Mapa de Calor' (Heatmap) generado por herramientas como Hotjar o Crazy Egg?", options:["Un mapa meteorológico, concepto diferente al que se describe en esta pregunta","Una representación gráfica basada en colores cálidos (rojo) y fríos (azul) que visualiza agregadamente dónde hacen clic, mueven el cursor o hacen scroll los usuarios en una página","Un mapa de temperatura de los servidores, concepto diferente al que se describe en esta pregunta","Un mapa de la red, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evidencia visualmente qué elementos acaparan la atención y qué partes de la página son completamente ignoradas.", noShuffle:false },
  { concept_id:"diw_u6_q11", unit:6, question:"¿Qué mide el 'Scroll Map' (Mapa de Scroll) en analítica de interfaces?", options:["La velocidad del ratón, concepto diferente al que se describe en esta pregunta","El porcentaje de visitantes que hace scroll hasta cada punto vertical de la página, mostrando hasta dónde bajan los usuarios antes de marcharse","El número de clics en la barra de scroll, concepto que se aplica en un contexto distinto","La longitud en píxeles del código, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite ubicar los contenidos más valiosos y llamadas a la acción antes de la línea donde la audiencia cae drásticamente.", noShuffle:false },
  { concept_id:"diw_u6_q12", unit:6, question:"¿Qué es el 'Eye Tracking' en investigación avanzada de interfaces?", options:["Un control ocular para jugar, concepto diferente al que se describe en esta pregunta","Una tecnología que rastrea y graba con precisión infrarroja hacia qué puntos exactos de la pantalla mira la pupila del usuario y durante cuántos milisegundos fija la vista (fijaciones y sacadas)","Un filtro de pantalla, concepto diferente al que se describe en esta pregunta","Un test de optometría, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Revela patrones objetivos de exploración visual inconsciente antes de que el usuario haga clic o tome una decisión.", noShuffle:false },
  { concept_id:"diw_u6_q13", unit:6, question:"¿Qué cuestionario estandarizado de 10 preguntas de opción múltiple (escala de 1 a 5) es el estándar de la industria para medir la usabilidad percibida con una puntuación de 0 a 100?", options:["SUS (System Usability Scale)","NPS (Net Promoter Score)","CSAT (Customer Satisfaction Score)","CES (Customer Effort Score)"], correct:0, explanation:"Una puntuación SUS por encima de 68 se considera usabilidad media aprobada; por encima de 80 es excelente.", noShuffle:false },
  { concept_id:"diw_u6_q14", unit:6, question:"¿Qué mide el indicador NPS (Net Promoter Score)?", options:["La velocidad del procesador, concepto diferente al que se describe en esta pregunta","La lealtad de los usuarios y su predisposición a recomendar el producto a un amigo o colega (en una escala del 0 al 10), clasificando en Promotores, Pasivos y Detractores","El número de páginas vistas, concepto que se aplica en un contexto distinto","La tasa de errores, concepto que se aplica en un contexto distinto"], correct:1, explanation:"NPS = % Promotores (9-10) - % Detractores (0-6). Es el estándar de satisfacción corporativa a nivel global.", noShuffle:false },
  { concept_id:"diw_u6_q15", unit:6, question:"¿Qué es una 'Evaluación Heurística' de una interfaz?", options:["Un test con 100 usuarios, concepto diferente al que se describe en esta pregunta","Una inspección crítica formal realizada por expertos en usabilidad que analizan cada pantalla contrastándola contra principios heurísticos establecidos (como los de Nielsen) sin necesidad de reclutar usuarios","Un escáner automático de código, concepto diferente al que se describe en esta pregunta","Un examen tipo test, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es un método rápido y económico para depurar la interfaz antes de realizar pruebas con usuarios reales.", noShuffle:false },
  { concept_id:"diw_u6_q16", unit:6, question:"¿Qué son las 'Core Web Vitals' establecidas por Google para evaluar la experiencia de usuario y el SEO técnico de una web?", options:["Tres consejos de diseño, concepto diferente al que se describe en esta pregunta","Un conjunto de tres métricas clave centradas en el usuario que miden: velocidad de carga visual (LCP), interactividad/capacidad de respuesta (INP) y estabilidad visual de la maqueta (CLS)","Tres colores obligatorios, concepto diferente al que se describe en esta pregunta","Tres navegadores compatibles, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Afectan directamente al ranking de búsqueda de Google y reflejan la fluidez real de la interfaz.", noShuffle:false },
  { concept_id:"diw_u6_q17", unit:6, question:"¿Qué mide la métrica Core Web Vital 'LCP' (Largest Contentful Paint)?", options:["El tiempo de renderizado del elemento de contenido visible más grande en pantalla; debe ser inferior a 2.5 segundos","La longitud total del archivo CSS, concepto diferente al que se describe en esta pregunta","El número de fuentes tipográficas, concepto que se aplica en un contexto distinto","El tamaño del logotipo, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Mide cuándo el usuario percibe que la página web ha cargado su contenido principal útil.", noShuffle:false },
  { concept_id:"diw_u6_q18", unit:6, question:"¿Qué métrica de Core Web Vitals sustituyó a FID para evaluar la latencia y respuesta ante interacciones del usuario (clics, toques, teclas) a lo largo de toda la visita?", options:["INP (Interaction to Next Paint; debe ser inferior a 200 milisegundos)","TTFB (Time to First Byte), concepto diferente al que se describe en esta pregunta","FCP (First Contentful Paint), concepto diferente al que se describe en esta pregunta","TBT (Total Blocking Time), concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"INP mide el retraso global de la interfaz al responder con una actualización visual tras cualquier interacción del usuario.", noShuffle:false },
  { concept_id:"diw_u6_q19", unit:6, question:"¿Qué mide la métrica Core Web Vital 'CLS' (Cumulative Layout Shift)?", options:["El cambio de tamaño del texto, concepto que se aplica en un contexto distinto","La puntuación que cuantifica la cantidad total de movimientos o saltos inesperados de layout que sufren los elementos visibles mientras se carga la página (debe ser inferior a 0.1)","La velocidad de conexión a internet, concepto que se aplica en un contexto distinto","El número de cookies, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Previene que un usuario vaya a hacer clic en un enlace y un salto repentino le haga pulsar un botón no deseado.", noShuffle:false },
  { concept_id:"diw_u6_q20", unit:6, question:"¿Qué es el 'Visual Regression Testing' (Pruebas de Regresión Visual)?", options:["Volver a diseñar la web desde cero, concepto diferente al que se describe en esta pregunta","Pruebas automatizadas que capturan capturas de pantalla de la interfaz tras cada cambio de código y las comparan píxel a píxel contra una versión de referencia para alertar de desajustes visuales involuntarios","Probar en navegadores antiguos, concepto diferente al que se describe en esta pregunta","Un test de daltonismo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Herramientas como Percy, Chromatic o Playwright evitan que un cambio en un archivo CSS global descoloque botones en otras páginas sin que nadie lo note.", noShuffle:false },
  { concept_id:"diw_u6_q21", unit:6, question:"¿Qué framework moderno de automatización de navegadores permite realizar pruebas End-to-End (E2E), capturas de pantalla y testeo visual multiplataforma?", options:["Playwright y Cypress","Photoshop, concepto diferente al que se describe en esta pregunta","FileZilla, concepto diferente al que se describe en esta pregunta","Word, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Playwright permite escribir tests en JavaScript/TypeScript que abren navegadores reales (Chromium, Firefox, WebKit) y ejecutan interacciones completas simuladas.", noShuffle:false },
  { concept_id:"diw_u6_q22", unit:6, question:"¿Qué es el 'Cross-Browser Testing' (Pruebas entre Navegadores)?", options:["Usar dos monitores a la vez, concepto diferente al que se describe en esta pregunta","Verificar que la interfaz web se visualiza, comporta y funciona de forma coherente en todos los principales motores y navegadores del mercado (Chromium/Chrome/Edge, Gecko/Firefox, WebKit/Safari)","Probar en dos sistemas operativos, concepto diferente al que se describe en esta pregunta","Cambiar el navegador predeterminado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Detecta inconsistencias de renderizado en propiedades CSS modernas o diferencias en la ejecución de APIs de JavaScript.", noShuffle:false },
  { concept_id:"diw_u6_q23", unit:6, question:"¿Qué plataformas en la nube permiten realizar pruebas manuales o automatizadas en miles de combinaciones de navegadores y dispositivos móviles reales sin tener que comprarlos físicamente?", options:["BrowserStack y Sauce Labs","Google Drive, concepto diferente al que se describe en esta pregunta","GitHub Pages, concepto diferente al que se describe en esta pregunta","Dropbox, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"BrowserStack proporciona acceso remoto a granjas de dispositivos físicos reales (iPhone, Samsung Galaxy, Mac, Windows) desde el navegador.", noShuffle:false },
  { concept_id:"diw_u6_q24", unit:6, question:"¿Qué es el 'Responsive Testing' y qué herramienta nativa de las DevTools lo facilita?", options:["Un test de velocidad de red, concepto diferente al que se describe en esta pregunta","El 'Modo de Diseño Responsivo' (Ctrl+Shift+M en Chrome/Firefox) que emula diferentes resoluciones, orientaciones y densidades de píxeles (DPR) de dispositivos móviles y tablets","Un validador de HTML, concepto diferente al que se describe en esta pregunta","La consola de errores, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Permite a los maquetadores ajustar media queries y probar puntos de ruptura de pantalla de forma ágil durante el desarrollo.", noShuffle:false },
  { concept_id:"diw_u6_q25", unit:6, question:"¿Qué es el 'Throttling' de red y CPU en las herramientas de desarrollo del navegador?", options:["Acelerar el ordenador, concepto diferente al que se describe en esta pregunta","La simulación deliberada de conexiones de red lentas para experimentar cómo carga la web en dispositivos de gama media-baja en la vida real","Un apagado de emergencia, concepto diferente al que se describe en esta pregunta","Un limpiador de caché, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evita el sesgo del desarrollador de probar siempre en ordenadores potentes con fibra óptica de alta velocidad.", noShuffle:false },
  { concept_id:"diw_u6_q26", unit:6, question:"¿Qué es la herramienta 'Wave' (Web Accessibility Evaluation Tool)?", options:["Un reproductor de audio, concepto diferente al que se describe en esta pregunta","Una suite de evaluación visual desarrollada por WebAIM que inyecta iconos descriptivos directamente sobre la página web auditada señalando errores de contraste, etiquetas faltantes y problemas ARIA","Un framework de CSS, concepto diferente al que se describe en esta pregunta","Un compresor de vídeo, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite a diseñadores y evaluadores ver de un vistazo qué elementos visuales exactos incumplen las pautas WCAG.", noShuffle:false },
  { concept_id:"diw_u6_q27", unit:6, question:"¿Qué simulador de visión integrado en Chrome DevTools permite comprobar cómo ven la web personas con distintos tipos de daltonismo?", options:["Rendering > Emulate vision deficiencies (Protanopia, Deuteranopia","Styles > Colors, concepto diferente al que se describe en esta pregunta","Console > Daltonism, concepto diferente al que se describe en esta pregunta","Network > Vision, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"Permite validar si la interfaz sigue siendo comprensible para usuarios que no perciben el espectro rojo-verde o azul-amarillo.", noShuffle:false },
  { concept_id:"diw_u6_q28", unit:6, question:"¿Qué es el 'Design Handoff' en el ciclo de vida del producto digital?", options:["Despedir al diseñador, concepto diferente al que se describe en esta pregunta","El momento y proceso de transferencia donde el equipo de diseño entrega los prototipos, especificaciones técnicas, assets vectoriales y guías al equipo de desarrollo frontend para su maquetación en código","El lanzamiento de la web al público, concepto que se aplica en un contexto distinto","El cobro del proyecto, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Herramientas como Figma Dev Mode o Zeplin estandarizan esta entrega para evitar discrepancias entre el diseño y la realidad.", noShuffle:false },
  { concept_id:"diw_u6_q29", unit:6, question:"¿Qué significa el término 'Fidelity' (Fidelidad) en el prototipado de interfaces?", options:["La fidelidad del usuario a la marca, concepto diferente al que se describe en esta pregunta","El nivel de detalle, realismo y cercanía visual e interactiva que tiene un prototipo respecto al producto final terminado (baja fidelidad = esquemas; alta fidelidad = réplica casi indistinguible)","La velocidad de conexión del prototipo, concepto que se aplica en un contexto distinto","El número de pantallas, concepto que se aplica en un contexto distinto"], correct:1, explanation:"Prototipos de baja fidelidad son rápidos para validar conceptos tempranos; los de alta fidelidad son ideales para pruebas de usabilidad finales.", noShuffle:false },
  { concept_id:"diw_u6_q30", unit:6, question:"¿Qué es el 'Card Sorting Abierto' frente al 'Card Sorting Cerrado'?", options:["No hay diferencia, aunque algunos enfoques establecen matices al respecto","En el abierto los usuarios agrupan las tarjetas de contenido y ellos mismos crean y nombran las categorías; en el cerrado los usuarios colocan las tarjetas dentro de categorías predeterminadas y cerradas por los investigadores","El abierto es gratis y el cerrado de pago, concepto diferente al que se describe en esta pregunta","El cerrado se hace con ordenador apagado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El abierto descubre cómo conceptualizan los usuarios la información; el cerrado valida si la arquitectura propuesta es comprensible.", noShuffle:false },
  { concept_id:"diw_u6_q31", unit:6, question:"¿Qué es un 'Task Completion Rate' (Tasa de Éxito de Tareas) en un test de usabilidad?", options:["La velocidad a la que escribe el usuario, concepto diferente al que se describe en esta pregunta","El porcentaje de participantes que logran completar satisfactoriamente una tarea específica asignada en la prueba sin requerir asistencia externa","El número de tareas falladas, concepto que se aplica en un contexto distinto","La hora de finalización del test, que puede confundirse con este termino en contabilidad general"], correct:1, explanation:"Es la métrica cuantitativa elemental de eficacia en cualquier prueba de usabilidad de producto.", noShuffle:false },
  { concept_id:"diw_u6_q32", unit:6, question:"¿Qué mide la métrica 'Time on Task' (Tiempo en Tarea)?", options:["La hora del reloj, que puede confundirse con este termino en contabilidad general","La cantidad de tiempo en segundos o minutos que le toma al usuario completar con éxito una tarea específica dentro de la interfaz","El tiempo que el servidor tarda en responder, aunque este indicador se calcula de forma diferente","El tiempo que dura la sesión de trabajo, aunque este indicador se calcula de forma diferente"], correct:1, explanation:"Permite comparar si un rediseño de interfaz hace a los usuarios más eficientes en tareas clave (como tramitar un pedido).", noShuffle:false },
  { concept_id:"diw_u6_q33", unit:6, question:"¿Qué es el 'Tree Testing' en investigación de arquitecturas de la información?", options:["Un test sobre árboles botánicos, concepto diferente al que se describe en esta pregunta","Una técnica que evalúa la encontrabilidad de contenidos en una versión de texto simplificada en forma de árbol jerárquico (sin diseño visual ni menús gráficos) para aislar la eficacia de la estructura","Un test de Git, concepto diferente al que se describe en esta pregunta","Una auditoría de seguridad, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Demuestra si los usuarios pueden encontrar secciones guiándose únicamente por las etiquetas de navegación, sin el sesgo del diseño gráfico.", noShuffle:false },
  { concept_id:"diw_u6_q34", unit:6, question:"¿Qué es el 'Guerilla Usability Testing' (Pruebas de Guerrilla)?", options:["Un ciberataque informático, concepto diferente al que se describe en esta pregunta","Una técnica informal y ágil de pruebas de bajo coste donde los investigadores se acercan a personas en espacios públicos (cafeterías, universidades) para probar un prototipo durante 5 o 10 minutos","Una prueba con militares, concepto diferente al que se describe en esta pregunta","Un test automatizado, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Ideal para startups o proyectos con presupuesto cero que necesitan retroalimentación inmediata sobre conceptos tempranos.", noShuffle:false },
  { concept_id:"diw_u6_q35", unit:6, question:"¿Qué papel desempeña un 'Checklist de Validación de Accesibilidad' antes de publicar una web?", options:["Gastar tiempo de desarrollo, concepto diferente al que se describe en esta pregunta","Garantizar mediante una lista de verificación exhaustiva que se han probado contrastes, navegación por teclado, textos alternativos, formularios y compatibilidad con lectores de pantalla","Desactivar los estilos CSS, concepto diferente al que se describe en esta pregunta","Un informe para el servidor, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Evita que descuidos elementales lleguen a producción comprometiendo la legalidad y accesibilidad de la web.", noShuffle:false },
  { concept_id:"diw_u6_q36", unit:6, question:"¿Qué es un 'Micro-Interacción' en diseño de interfaces y cómo se valida?", options:["Una transacción bancaria de pocos céntimos, concepto diferente al que se describe en esta pregunta","Un momento interactivo sutil y específico diseñado alrededor de una única tarea o feedback visual","Un componente de 1 píxel, concepto diferente al que se describe en esta pregunta","Un clic de ratón, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Las micro-interacciones deleitan al usuario y proporcionan retroalimentación inmediata haciéndolo sentir que el sistema está vivo.", noShuffle:false },
  { concept_id:"diw_u6_q37", unit:6, question:"¿Qué servicio online permite probar cómo se verá una página web en múltiples clientes de correo electrónico (Outlook, Gmail, Apple Mail)?", options:["Litmus o Email on Acid","Photoshop, concepto diferente al que se describe en esta pregunta","FileZilla, concepto diferente al que se describe en esta pregunta","Slack, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"El diseño de newsletters y emails HTML sufre enormes diferencias de renderizado entre clientes, requiriendo validación especializada.", noShuffle:false },
  { concept_id:"diw_u6_q38", unit:6, question:"¿Qué es el 'First Input Delay' (FID) histórico y por qué fue superado por INP?", options:["FID solo medía el retraso de la primera interacción que hacía el usuario al llegar; INP evalúa la peor latencia de todas las interacciones a lo largo de toda la navegación del usuario","FID medía imágenes, concepto diferente al que se describe en esta pregunta","FID era solo para móviles, concepto diferente al que se describe en esta pregunta","Son exactamente iguales, concepto diferente al que se describe en esta pregunta"], correct:0, explanation:"INP proporciona una visión holística mucho más representativa de si la web responde con fluidez continua o si se congela periódicamente.", noShuffle:false },
  { concept_id:"diw_u6_q39", unit:6, question:"¿Qué es una 'Sesión Grabada' (Session Recording / Replay) en herramientas como Hotjar o FullStory?", options:["Una videollamada con el usuario, concepto diferente al que se describe en esta pregunta","Una recreación visual anonimizada de los movimientos reales de ratón","Una grabación de la cámara web del usuario, concepto diferente al que se describe en esta pregunta","Un vídeo promocional, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Permite ver exactamente en qué punto del flujo los usuarios se confunden, se atascan en un formulario o experimentan un bug visual.", noShuffle:false },
  { concept_id:"diw_u6_q40", unit:6, question:"¿Qué es el 'Rage Click' (Clic de Rabia) detectado por herramientas de analítica UX?", options:["Un virus de teclado, concepto diferente al que se describe en esta pregunta","Cuando un usuario pulsa repetida y rápidamente un elemento muchas veces en pocos segundos porque espera que sea interactivo pero la interfaz no responde, señalando un grave problema de usabilidad o un botón roto","Un juego de ordenador, concepto diferente al que se describe en esta pregunta","Un clic doble, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Es uno de los indicadores automáticos más claros de frustración y fricción en la experiencia de usuario.", noShuffle:false },
  { concept_id:"diw_u6_q41", unit:6, question:"¿Por qué las pruebas de usabilidad deben incluir a personas con diversas discapacidades reales?", options:["Por postureo corporativo, concepto diferente al que se describe en esta pregunta","Porque proporcionan perspectivas incomparables y auténticas sobre barreras de interacción reales que ningún desarrollador sin discapacidad puede simular o prever por completo","Porque cobran menos, concepto diferente al que se describe en esta pregunta","Para probar en ordenadores viejos, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"Involucrar a usuarios de lectores de pantalla, personas con discapacidad motriz o visual asegura un diseño verdaderamente inclusivo y universal.", noShuffle:false },
  { concept_id:"diw_u6_q42", unit: earthy = false, unit:6, question:"¿Cuál es la diferencia entre testing cuantitativo y cualitativo en UX?", options:["No hay diferencia, aunque algunos enfoques establecen matices al respecto","El cuantitativo responde a 'CUÁNTO' mediante números y métricas medibles a escala (tasas de conversión, tiempos, porcentajes de éxito); el cualitativo responde a 'POR QUÉ' mediante observación directa, opiniones y comprensiones profundas de las motivaciones humanas","El cualitativo solo usa números, concepto diferente al que se describe en esta pregunta","El cuantitativo se hace sin ordenadores, concepto diferente al que se describe en esta pregunta"], correct:1, explanation:"El cuantitativo detecta dónde está el problema en el embudo; el cualitativo explica por qué ocurre y cómo resolverlo.", noShuffle:false }
];
